frontend/js/config.js.source:
/**
 * Configuración del dashboard y preferencias persistentes del usuario.
 *
 * Prioridad para la dirección del servidor:
 *   1. ?server=http://10.0.0.5:8001  en la URL (ideal para el día del robot real)
 *   2. lo último que se usó (localStorage)
 *   3. el mismo origen, si el dashboard lo sirve el propio backend
 *   4. "demo" (simulador en el navegador) si está publicado en GitHub Pages
 *   5. http://localhost:8001
 */
const STORAGE_KEY = "tp05-dashboard";

export const DEFAULTS = Object.freeze({
  transport: "websocket",   // "websocket" | "polling"
  intervalMs: 250,          // polling: la consigna pide como máximo 500 ms
  historySize: 600,         // muestras en memoria (~60 s a 10 Hz)
  chartWindow: 150,         // muestras visibles en los gráficos (≥ 60 por consigna)
  torqueAlarm: 18,          // N·m: umbral de alarma de torque
});

function readAll() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}");
  } catch {
    return {}; // modo privado, almacenamiento bloqueado o JSON corrupto
  }
}

export const settings = {
  get(key, fallback = undefined) {
    return readAll()[key] ?? fallback;
  },
  set(key, value) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...readAll(), [key]: value }));
    } catch { /* sin persistencia: no es crítico */ }
  },
};

export function resolveInitialServer(location = window.location) {
  const fromQuery = new URLSearchParams(location.search).get("server");
  if (fromQuery) return fromQuery;
  const saved = settings.get("baseUrl");
  if (saved) return saved;
  if (location.protocol.startsWith("http") && location.pathname.startsWith("/dashboard")) {
    return location.origin;
  }
  if (location.hostname.endsWith("github.io")) return "demo";
  return "http://localhost:8001";
}

/** Último backend real usado (para volver a él desde la simulación del navegador). */
export function resolveBackendUrl(location = window.location) {
  const saved = settings.get("backendUrl");
  if (saved) return saved;
  if (location.protocol.startsWith("http") && location.pathname.startsWith("/dashboard")) return location.origin;
  return "http://localhost:8001";
}

export function resolveInitialTransport(location = window.location) {
  const q = new URLSearchParams(location.search).get("transport");
  if (q === "polling" || q === "websocket") return q;
  return settings.get("transport", DEFAULTS.transport);
}

frontend/js/core/CaptureStore.js.source:
/**
 * Almacén de muestras capturadas durante la sesión.
 *
 * Replica el botón "Capturar" de electroSim: cada captura congela una copia
 * del estado completo del robot. Además permite una grabación continua
 * (todas las muestras que llegan) con un tope para no agotar la memoria.
 */
export class CaptureStore {
  #samples = [];
  #listeners = new Set();

  constructor({ maxSamples = 50_000 } = {}) {
    this.maxSamples = maxSamples;
  }

  get size() {
    return this.#samples.length;
  }

  get samples() {
    return this.#samples;
  }

  /** @returns {object|null} la captura agregada, o null si se llegó al tope */
  add(frame, tipo = "manual") {
    if (!frame) return null;
    if (this.#samples.length >= this.maxSamples) return null;
    const sample = {
      n: this.#samples.length + 1,
      tipo,
      capturedAt: new Date(frame.receivedAt ?? Date.now()),
      frame: structuredClone(frame),
    };
    this.#samples.push(sample);
    this.#notify();
    return sample;
  }

  clear() {
    this.#samples = [];
    this.#notify();
  }

  subscribe(fn) {
    this.#listeners.add(fn);
    return () => this.#listeners.delete(fn);
  }

  #notify() {
    for (const fn of this.#listeners) fn(this);
  }
}

frontend/js/core/EventBus.js.source:
/**
 * EventBus — patrón Observer (publicador / suscriptor).
 *
 * Los transportes publican eventos ("frame", "connection", "info") sin saber
 * quién los escucha; los paneles se suscriben sin saber de dónde salen los
 * datos. Ese desacople es lo que permite cambiar WebSocket por polling (o el
 * simulador por el robot real) sin tocar una sola línea de la UI.
 */
export class EventBus {
  #listeners = new Map();

  /** Suscribe `handler` a `event`. Devuelve una función para desuscribirse. */
  on(event, handler) {
    if (!this.#listeners.has(event)) this.#listeners.set(event, new Set());
    this.#listeners.get(event).add(handler);
    return () => this.off(event, handler);
  }

  off(event, handler) {
    this.#listeners.get(event)?.delete(handler);
  }

  /** Notifica a todos los suscriptores. Un suscriptor que falla no rompe al resto. */
  emit(event, payload) {
    for (const handler of this.#listeners.get(event) ?? []) {
      try {
        handler(payload);
      } catch (err) {
        console.error(`[EventBus] Error en un suscriptor de "${event}"`, err);
      }
    }
  }
}

frontend/js/core/RingBuffer.js.source:
/**
 * RingBuffer — buffer circular de capacidad fija.
 *
 * Guarda las últimas N muestras de telemetría para los gráficos históricos.
 * `push` es O(1) y la memoria es constante: a 10 Hz, en una clase de 2 horas
 * llegan 72.000 muestras; con un array que crece sin límite el navegador se
 * pondría cada vez más lento. Acá nunca hay más de `capacity` elementos.
 */
export class RingBuffer {
  #items;
  #start = 0;
  #size = 0;

  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("La capacidad debe ser un entero positivo");
    }
    this.capacity = capacity;
    this.#items = new Array(capacity);
  }

  get size() {
    return this.#size;
  }

  push(item) {
    const end = (this.#start + this.#size) % this.capacity;
    this.#items[end] = item;
    if (this.#size < this.capacity) this.#size += 1;
    else this.#start = (this.#start + 1) % this.capacity; // pisa el más viejo
  }

  /** Elemento i-ésimo, del más viejo (0) al más nuevo (size-1). */
  at(i) {
    if (i < 0) i += this.#size;
    if (i < 0 || i >= this.#size) return undefined;
    return this.#items[(this.#start + i) % this.capacity];
  }

  last() {
    return this.at(-1);
  }

  /** Las últimas `n` muestras (o todas), en orden cronológico. */
  tail(n = this.#size) {
    const count = Math.min(n, this.#size);
    const out = new Array(count);
    for (let i = 0; i < count; i++) out[i] = this.at(this.#size - count + i);
    return out;
  }

  clear() {
    this.#start = 0;
    this.#size = 0;
    this.#items = new Array(this.capacity);
  }
}

frontend/js/core/alerts.js.source:
/**
 * Reglas de alarma. Funciones puras (sin DOM) para poder testearlas.
 *
 * `evaluateAlerts` dice qué condiciones están activas en una muestra.
 * `AlertTracker` compara con la muestra anterior y solo informa los CAMBIOS
 * (se activó / se normalizó). Sin eso, un motor a 61 °C dispararía 10
 * notificaciones por segundo.
 *
 * Histéresis: una alarma se activa al pasar el umbral, pero se apaga recién
 * un poco por debajo (60 °C → 58 °C; torque → 90 % del umbral). Así un motor
 * que oscila entre 59,9 y 60,1 °C no prende y apaga el aviso sin parar, igual
 * que un termostato.
 */

export const HYSTERESIS = Object.freeze({ tempC: 2, torqueRatio: 0.9, socPct: 2 });
import { TEMP_THRESHOLDS } from "./telemetryModel.js";

/**
 * @param {object} frame muestra normalizada
 * @param {object} opts  umbrales
 * @param {Set<string>} [wasActive] claves activas en la muestra anterior (para la histéresis)
 */
export function evaluateAlerts(frame, { torqueAlarm = 18, socAlarm = 20 } = {}, wasActive = new Set()) {
  const active = [];
  const on = (key, value, threshold, release, above = true) =>
    wasActive.has(key) ? (above ? value > release : value < release) : above ? value > threshold : value < threshold;

  for (const m of frame.motores) {
    if (on(`temp:${m.nombre}`, m.temperatura, TEMP_THRESHOLDS.crit, TEMP_THRESHOLDS.crit - HYSTERESIS.tempC)) {
      active.push({ key: `temp:${m.nombre}`, level: "crit", message: `${m.nombre} a ${m.temperatura.toFixed(0)} °C (> ${TEMP_THRESHOLDS.crit} °C)` });
    }
    if (on(`tau:${m.nombre}`, Math.abs(m.torque), torqueAlarm, torqueAlarm * HYSTERESIS.torqueRatio)) {
      active.push({ key: `tau:${m.nombre}`, level: "warn", message: `Torque de ${m.nombre}: ${Math.abs(m.torque).toFixed(1)} N·m (> ${torqueAlarm} N·m)` });
    }
  }
  if (frame.bms.soc > 0 && on("soc", frame.bms.soc, socAlarm, socAlarm + HYSTERESIS.socPct, false)) {
    active.push({ key: "soc", level: "crit", message: `Batería baja: ${frame.bms.soc} %` });
  }
  return active;
}

export class AlertTracker {
  #active = new Map();

  /** @returns {{raised: object[], cleared: object[], active: object[]}} */
  update(alerts) {
    const next = new Map(alerts.map((a) => [a.key, a]));
    const raised = alerts.filter((a) => !this.#active.has(a.key));
    const cleared = [...this.#active.values()].filter((a) => !next.has(a.key));
    this.#active = next;
    return { raised, cleared, active: alerts };
  }

  /** Claves activas, para pasarle a evaluateAlerts (histéresis). */
  get keys() {
    return new Set(this.#active.keys());
  }

  reset() {
    this.#active.clear();
  }
}

frontend/js/core/csv.js.source:
/**
 * Exportación CSV de las muestras capturadas.
 *
 * Formato "ancho": una fila por muestra y una columna por variable, que es lo
 * que esperan Excel, LibreOffice, pandas o MATLAB. Las columnas se generan a
 * partir de los datos (12 motores para Go2, 29 para G1; N celdas de batería).
 */

/** Escapa un campo según RFC 4180: comillas si contiene separador, comillas o saltos. */
export function escapeCsv(value, sep = ",") {
  if (value === null || value === undefined) return "";
  const s = String(value);
  return s.includes(sep) || s.includes('"') || s.includes("\n") || s.includes("\r")
    ? `"${s.replaceAll('"', '""')}"`
    : s;
}

/** Arma las columnas a partir de todas las muestras (unión de motores, celdas y patas). */
export function buildColumns(samples) {
  const motors = [];
  const seenMotors = new Set();
  const legs = [];
  let maxCells = 0;

  for (const { frame } of samples) {
    for (const m of frame.motores) {
      if (!seenMotors.has(m.nombre)) {
        seenMotors.add(m.nombre);
        motors.push(m.nombre);
      }
    }
    for (const pata of Object.keys(frame.fuerzas)) if (!legs.includes(pata)) legs.push(pata);
    maxCells = Math.max(maxCells, frame.bms.celdas.length);
  }

  const cols = [
    { header: "captura", get: (s) => s.n },
    { header: "tipo", get: (s) => s.tipo },
    { header: "fecha_hora_iso", get: (s) => s.capturedAt.toISOString() },
    { header: "ts_servidor_s", get: (s) => s.frame.ts, numeric: true },
    { header: "modelo", get: (s) => s.frame.modelo },
    { header: "imu_roll_deg", get: (s) => s.frame.imu.roll, numeric: true },
    { header: "imu_pitch_deg", get: (s) => s.frame.imu.pitch, numeric: true },
    { header: "imu_yaw_deg", get: (s) => s.frame.imu.yaw, numeric: true },
    { header: "imu_ax_ms2", get: (s) => s.frame.imu.ax, numeric: true },
    { header: "imu_ay_ms2", get: (s) => s.frame.imu.ay, numeric: true },
    { header: "imu_az_ms2", get: (s) => s.frame.imu.az, numeric: true },
    { header: "bms_soc_pct", get: (s) => s.frame.bms.soc, numeric: true },
    { header: "bms_corriente_mA", get: (s) => s.frame.bms.corriente, numeric: true },
    { header: "bms_temperatura_C", get: (s) => s.frame.bms.temperatura, numeric: true },
  ];
  for (let i = 0; i < maxCells; i++) {
    cols.push({ header: `bms_celda_${i + 1}_V`, get: (s) => s.frame.bms.celdas[i], numeric: true });
  }
  for (const pata of legs) {
    cols.push({ header: `pata_${pata}_contacto`, get: (s) => s.frame.fuerzas[pata], numeric: true });
  }
  const fields = [
    ["angulo", "deg"],
    ["velocidad", "rads"],
    ["torque", "Nm"],
    ["temperatura", "C"],
  ];
  for (const nombre of motors) {
    for (const [field, unit] of fields) {
      cols.push({
        header: `${nombre}_${field}_${unit}`,
        get: (s) => s.frame.motores.find((m) => m.nombre === nombre)?.[field],
        numeric: true,
      });
    }
  }
  return cols;
}

/**
 * Genera el texto CSV.
 * @param {Array} samples muestras de CaptureStore
 * @param {{excel?: boolean}} opts excel=true usa ";" y coma decimal (Excel en español)
 */
export function toCsv(samples, { excel = false } = {}) {
  const sep = excel ? ";" : ",";
  const cols = buildColumns(samples);
  const fmt = (value, numeric) => {
    if (numeric && excel && typeof value === "number") return String(value).replace(".", ",");
    return value;
  };
  const lines = [cols.map((c) => escapeCsv(c.header, sep)).join(sep)];
  for (const s of samples) {
    lines.push(cols.map((c) => escapeCsv(fmt(c.get(s), c.numeric), sep)).join(sep));
  }
  return lines.join("\r\n") + "\r\n";
}

/** Nombre de archivo con fecha local: telemetria_go2_2026-10-29_17-30-05.csv */
export function csvFilename(modelo, date = new Date(), ext = "csv") {
  const p = (n) => String(n).padStart(2, "0");
  const stamp = `${date.getFullYear()}-${p(date.getMonth() + 1)}-${p(date.getDate())}_${p(date.getHours())}-${p(date.getMinutes())}-${p(date.getSeconds())}`;
  return `telemetria_${modelo}_${stamp}.${ext}`;
}

/** Dispara la descarga en el navegador. El BOM hace que Excel lea bien los acentos. */
export function downloadText(text, filename, mime = "text/csv;charset=utf-8") {
  const bom = mime.startsWith("text/csv") ? "﻿" : "";
  const blob = new Blob([bom + text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement("a"), { href: url, download: filename });
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

frontend/js/core/paseoSim.js.source:
/**
 * Simulador "paseo" en el navegador: port a JavaScript de
 * backend/api/demo_paseo.py, para poder usar el dashboard SIN servidor
 * (por ejemplo, publicado en GitHub Pages).
 *
 * Produce exactamente el JSON de GET /telemetria y GET /info (ya adaptado:
 * grados, voltios, roll/pitch/yaw), así que para el resto del dashboard es
 * indistinguible del backend real. Mismo guion, misma marcha al trote y mismo
 * modelo térmico que el demo de Python.
 */

export const ROBOTS = {
  go2: {
    nombre: "Unitree Go2 EDU",
    tipo: "cuadrupedo",
    patas: ["FR", "FL", "RR", "RL"],
    motores_nombres: ["FR_hip", "FR_thigh", "FR_calf", "FL_hip", "FL_thigh", "FL_calf", "RR_hip", "RR_thigh", "RR_calf", "RL_hip", "RL_thigh", "RL_calf"],
  },
  g1: {
    nombre: "Unitree G1 EDU",
    tipo: "humanoide",
    patas: ["R_foot", "L_foot"],
    motores_nombres: [
      "L_hip_pitch", "L_hip_roll", "L_hip_yaw", "L_knee", "L_ankle_pitch", "L_ankle_roll",
      "R_hip_pitch", "R_hip_roll", "R_hip_yaw", "R_knee", "R_ankle_pitch", "R_ankle_roll",
      "torso_yaw", "torso_roll", "torso_pitch",
      "L_shoulder_pitch", "L_shoulder_roll", "L_shoulder_yaw", "L_elbow", "L_wrist_roll", "L_wrist_pitch", "L_wrist_yaw",
      "R_shoulder_pitch", "R_shoulder_roll", "R_shoulder_yaw", "R_elbow", "R_wrist_roll", "R_wrist_pitch", "R_wrist_yaw",
    ],
  },
};

/** [duración s, velocidad 0..1, giro °/s, etiqueta] — igual que GUION en Python. */
export const GUION = [
  [6, 0, 0, "quieto"],
  [10, 0.55, 0, "camina"],
  [5, 0.55, 18, "curva izquierda"],
  [12, 1, 0, "trota"],
  [4, 0.3, -30, "gira derecha"],
  [7, 0, 0, "quieto"],
  [14, 0.85, 6, "camina rápido"],
  [5, 0, 0, "quieto"],
];

const T_AMB = 30;
const K_CALOR = 1.75;
const DEG = 180 / Math.PI;

/** Generador pseudoaleatorio con semilla (mulberry32): resultados reproducibles. */
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const smooth = (cur, target, dt, tau) => cur + (target - cur) * (1 - Math.exp(-dt / tau));

export class PaseoSim {
  constructor(modelo = "go2", { seed = 7 } = {}) {
    if (!ROBOTS[modelo]) throw new Error(`Modelo desconocido: ${modelo}`);
    this.modelo = modelo;
    this.cfg = ROBOTS[modelo];
    this.rand = rng(seed);
    this.gauss = (sd) => {
      const u = 1 - this.rand();
      const v = this.rand();
      return sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };
    this.t = 0;
    this.fase = 0;
    this.vel = 0;
    this.giro = 0;
    this.yaw = (this.rand() - 0.5) * 1;
    this.soc = 92;
    this.batTemp = 29;
    this.cellOffset = Array.from({ length: 8 }, (_, i) => (this.rand() - 0.5) * 12 - (i === 5 ? 14 : 0));
    this.motors = this.cfg.motores_nombres.map((n) => this.#motor(n));
    this.qPrev = new Array(this.motors.length).fill(0);
    this.steps = 0;
  }

  #motor(n) {
    let nominal;
    if (this.modelo === "go2") nominal = n.includes("calf") ? 22 : n.includes("thigh") ? 20 : 9;
    else nominal = n.includes("knee") ? 36 : n.includes("hip_pitch") ? 26 : n.includes("ankle") ? 20 : 9;
    const k = K_CALOR * (n.includes("calf") || n.includes("knee") ? 1.25 : 1) * (0.85 + this.rand() * 0.35);
    return { k, nominal, tauTh: 35 + this.rand() * 15, temp: T_AMB + 1 + this.rand() * 3 };
  }

  get tramo() {
    const total = GUION.reduce((a, [d]) => a + d, 0);
    let t = this.t % total;
    // t < total: si no cae en ningún tramo anterior, está en el último.
    for (const [d, v, g, label] of GUION.slice(0, -1)) {
      if (t < d) return { v, g, label };
      t -= d;
    }
    const [, v, g, label] = GUION.at(-1);
    return { v, g, label };
  }

  info() {
    return {
      modelo: this.modelo,
      nombre: this.cfg.nombre,
      tipo: this.cfg.tipo,
      n_motores: this.cfg.motores_nombres.length,
      motores_nombres: [...this.cfg.motores_nombres],
      patas: [...this.cfg.patas],
      frecuencia_hz: 10,
      modo: "demo",
    };
  }

  /** Avanza `dt` segundos integrando a 50 Hz. */
  advance(dt) {
    const h = 1 / 50;
    for (let left = dt; left > 1e-9; left -= h) this.#step(Math.min(h, left));
  }

  #step(dt) {
    this.t += dt;
    this.steps += 1;
    const { v, g } = this.tramo;
    this.vel = smooth(this.vel, v, dt, 0.8);
    this.giro = smooth(this.giro, g, dt, 0.6);
    this.yaw += (this.giro / DEG) * dt;
    this.yaw = ((this.yaw + Math.PI) % (2 * Math.PI) + 2 * Math.PI) % (2 * Math.PI) - Math.PI;
    if (this.vel > 0.02) this.fase = (this.fase + 2 * Math.PI * (1.6 + 0.9 * this.vel) * dt) % (2 * Math.PI);

    const { q, tau, feet } = this.modelo === "go2" ? this.#quadruped() : this.#biped();
    this.q = q;
    this.dq = q.map((x, i) => (this.steps > 1 ? (x - this.qPrev[i]) / dt : 0));
    this.qPrev = q;
    this.tau = tau;
    this.feet = feet;
    this.motors.forEach((m, i) => {
      const load = tau[i] / m.nominal;
      m.temp += (m.k * load * load - (m.temp - T_AMB) / m.tauTh) * dt;
    });

    const effort = tau.reduce((a, b) => a + Math.abs(b), 0) / tau.length;
    this.current = 1400 + 520 * effort + this.gauss(40);
    this.soc -= (this.current / 1000) * dt * 0.0045;
    if (this.soc < 12) this.soc = 96;
    this.batTemp = smooth(this.batTemp, 28 + this.current / 900, dt, 60);
  }

  #quadruped() {
    const a = this.vel;
    const desfase = { FR: 0, FL: Math.PI, RR: Math.PI, RL: 0 };
    const q = [];
    const tau = [];
    const feet = [];
    for (const pata of this.cfg.patas) {
      const f = this.fase + desfase[pata];
      const s = Math.sin(f);
      const c = Math.cos(f);
      const air = a > 0.05 && s > 0.15;
      const side = pata.endsWith("R") ? 1 : -1;
      const load = air ? 0.25 : 1;
      q.push((side * (1.5 + 3 * a * c)) / DEG, (45 + 22 * a * s) / DEG, (-88 - 28 * a * Math.max(0, s)) / DEG);
      tau.push((1.2 + 2.5 * a * Math.abs(c)) * side, 6 * load + 9 * a * Math.abs(s), -(9 * load + 13 * a * (0.5 + 0.5 * Math.abs(c))));
      feet.push(air ? 0 : 60 + 35 * a);
    }
    return { q, tau: tau.map((x) => x + this.gauss(0.15)), feet };
  }

  #biped() {
    const a = this.vel;
    const s = Math.sin(this.fase);
    const c = Math.cos(this.fase);
    const q = [];
    const tau = [];
    for (const n of this.cfg.motores_nombres) {
      const sign = n.startsWith("L_") ? 1 : -1;
      const sp = sign * s;
      let ang;
      let t;
      if (n.includes("hip_pitch")) [ang, t] = [-12 + 25 * a * sp, 8 + 10 * a * Math.abs(sp)];
      else if (n.includes("knee")) [ang, t] = [28 + 30 * a * Math.max(0, -sp), 18 + 14 * a * Math.abs(sp)];
      else if (n.includes("ankle_pitch")) [ang, t] = [-14 + 12 * a * sp, 9 + 8 * a * Math.abs(c)];
      else if (n.includes("shoulder_pitch")) [ang, t] = [10 - 20 * a * sp, 1.5 + 1.5 * a * Math.abs(sp)];
      else if (n.includes("elbow")) [ang, t] = [60 + 8 * a * c, 1.2 + 0.8 * a];
      else if (n.startsWith("torso_yaw")) [ang, t] = [4 * a * s, 3 + 5 * a * Math.abs(s)];
      else [ang, t] = [3 * a * sign * c, 1 + 1.5 * a * Math.abs(c)];
      q.push(ang / DEG);
      tau.push(t + this.gauss(0.15));
    }
    const airL = a > 0.05 && s > 0.2;
    const airR = a > 0.05 && s < -0.2;
    return { q, tau, feet: [airR ? 0 : 220, airL ? 0 : 220] };
  }

  /** La muestra con el formato de GET /telemetria. */
  telemetria() {
    const a = this.vel;
    const r2 = (x) => Math.round(x * 100) / 100;
    const roll = 2.2 * a * Math.sin(this.fase) + 0.25 * Math.sin(this.t * 0.7);
    const pitch = -1.2 * a + 1.6 * a * Math.cos(2 * this.fase) + 0.2 * Math.sin(this.t * 0.5);
    const vBase = 3300 + 9 * this.soc - this.current * 0.012;
    return {
      modelo: this.modelo,
      ts: r2(this.t),
      motores: this.motors.map((m, i) => ({
        id: i,
        nombre: this.cfg.motores_nombres[i],
        angulo: r2(this.q[i] * DEG),
        velocidad: Math.round(this.dq[i] * 1000) / 1000,
        torque: r2(this.tau[i]),
        temperatura: Math.round(m.temp),
      })),
      imu: {
        roll: r2(roll),
        pitch: r2(pitch),
        yaw: r2(this.yaw * DEG),
        ax: Math.round((0.35 * a * Math.cos(this.fase) + this.gauss(0.02)) * 1000) / 1000,
        ay: Math.round((0.25 * a * Math.sin(this.fase) + this.gauss(0.02)) * 1000) / 1000,
        az: Math.round((9.81 + 0.9 * a * Math.sin(2 * this.fase) + this.gauss(0.03)) * 1000) / 1000,
      },
      bms: {
        soc: Math.trunc(this.soc),
        corriente: Math.trunc(this.current),
        temperatura: Math.round(this.batTemp * 10) / 10,
        celdas: this.cellOffset.map((off) => Math.round(vBase + off + this.gauss(1.5)) / 1000),
      },
      fuerzas: Object.fromEntries(this.cfg.patas.map((p, i) => [p, this.feet[i] > 10 ? 1 : 0])),
    };
  }
}

