frontend/js/services/PollingTransport.js.source:
/**
 * Transporte "pull" por polling HTTP a GET /telemetria.
 *
 * Se usa `setTimeout` encadenado y NO `setInterval`: la próxima petición se
 * programa recién cuando terminó la anterior. Con `setInterval`, si el
 * servidor tarda más que el intervalo, las peticiones se apilan y llegan
 * fuera de orden. La consigna pide un intervalo máximo de 500 ms.
 */
import { ApiClient } from "./ApiClient.js";

export const MAX_POLL_INTERVAL_MS = 500;

export class PollingTransport {
  name = "polling";
  label = "Polling";
  #timer = null;
  #stopped = true;
  #abort = null;
  #failures = 0;

  constructor({ baseUrl, onData, onState, intervalMs = 250 }) {
    this.api = new ApiClient(baseUrl, { timeoutMs: 2000 });
    this.onData = onData;
    this.onState = onState;
    this.intervalMs = Math.min(MAX_POLL_INTERVAL_MS, Math.max(50, intervalMs));
    this.lastRttMs = null;
  }

  start() {
    this.#stopped = false;
    this.onState("connecting", `${this.api.baseUrl}/telemetria`);
    this.#tick();
  }

  stop() {
    this.#stopped = true;
    clearTimeout(this.#timer);
    this.#abort?.abort();
    this.#abort = null;
  }

  async #tick() {
    if (this.#stopped) return;
    const t0 = performance.now();
    // Cada ciclo es dueño de su controlador: si después de un stop() (y quizá un start())
    // ya no es el actual, la respuesta o el error se descartan y el ciclo muere (spec 010 · FR-011).
    const abort = (this.#abort = new AbortController());
    try {
      const raw = await this.api.telemetria({ signal: abort.signal });
      if (abort !== this.#abort) return;
      this.lastRttMs = performance.now() - t0;
      this.#failures = 0;
      this.onState("live");
      this.onData(raw, { rttMs: this.lastRttMs });
    } catch (err) {
      if (abort !== this.#abort) return;
      this.#failures += 1;
      this.onState("reconnecting", err.message);
    }
    // Si hay errores se espera más (hasta 4 s) para no martillar un servidor caído.
    const wait = this.#failures
      ? Math.min(4000, this.intervalMs * 2 ** this.#failures)
      : Math.max(0, this.intervalMs - (performance.now() - t0));
    this.#timer = setTimeout(() => this.#tick(), wait);
  }
}

frontend/js/services/SimTransport.js.source:
/**
 * Transporte "simulado": genera la telemetría en el propio navegador con
 * PaseoSim, sin servidor. Implementa la misma interfaz que WebSocketTransport
 * y PollingTransport (Strategy), así que el resto del dashboard no se entera.
 *
 * Se activa con  ?server=demo  (o ?server=demo-g1), y es lo que usa la
 * versión publicada en GitHub Pages.
 */
import { PaseoSim } from "../core/paseoSim.js";

export const isSimUrl = (url) => /^demo(-g1|-go2)?$/i.test(String(url ?? "").trim());
export const simModel = (url) => (/g1$/i.test(String(url)) ? "g1" : "go2");

export class SimTransport {
  name = "sim";
  label = "Simulador local";
  #timer = null;
  #last = 0;

  constructor({ baseUrl, onData, onState, rateHz = 10, warmupS = 25 }) {
    this.sim = new PaseoSim(simModel(baseUrl));
    // Arranca ya "caminando un rato" para que no se vea todo frío y quieto.
    this.sim.advance(warmupS);
    this.onData = onData;
    this.onState = onState;
    this.periodMs = 1000 / rateHz;
  }

  info() {
    return this.sim.info();
  }

  start() {
    this.onState("connecting", "simulador en el navegador");
    this.#last = performance.now();
    this.#timer = setInterval(() => {
      const now = performance.now();
      this.sim.advance(Math.min(0.5, (now - this.#last) / 1000));
      this.#last = now;
      this.onState("live");
      this.onData(this.sim.telemetria());
    }, this.periodMs);
  }

  stop() {
    clearInterval(this.#timer);
  }
}

