/**
 * Panel de batería (BMS): carga, corriente, temperatura y la tensión de cada
 * celda. En el dibujo el cuerpo del robot ya se llena con el SOC; acá están
 * los números que pide la consigna.
 */
import { h, setText, fmt, clamp } from "../../ui/dom.js";
import { socLevel } from "../../core/telemetryModel.js";
import { icon } from "../../ui/icons.js";
import { milliamps, currentSense } from "./format.js";

/** Rango de tensión de una celda de litio, para la altura de las barras. */
const CELL_MIN_V = 3.0;
const CELL_MAX_V = 4.25;
/** Desbalance a partir del cual se marca la celda más baja. */
const CELL_DELTA_WARN_MV = 30;

export class BatteryPanel {
  constructor() {
    this.soc = h("span", { class: "bd-num" }, "—");
    this.current = h("b", { class: "bd-num" }, "—");
    this.sense = h("span", { class: "bd-battery__sense" }, "");
    this.temp = h("b", { class: "bd-num" }, "—");
    this.pack = h("b", { class: "bd-num" }, "—");
    this.cells = h("div", { class: "bd-cells", role: "list", "aria-label": "Tensión de cada celda" });
    this.caption = h("span", {}, "");
    this.delta = h("span", { class: "bd-num" }, "");
    this.cellEls = [];
    this.el = h(
      "section",
      { class: "bd-battery", "aria-labelledby": "bd-battery-title" },
      h("h2", { class: "bd-eyebrow", id: "bd-battery-title", html: `${icon("battery", { size: 14 })}<span>Batería (BMS)</span>` }),
      h("div", { class: "bd-battery__main" },
        h("div", { class: "bd-battery__soc", title: "Estado de carga (SOC)" }, this.soc, h("small", {}, "%")),
        h("dl", { class: "bd-battery__meta" },
          h("div", {}, h("dt", {}, "Corriente"), h("dd", {}, this.current, this.sense)),
          h("div", {}, h("dt", {}, "Temperatura"), h("dd", {}, this.temp)),
          h("div", {}, h("dt", {}, "Pack"), h("dd", {}, this.pack)))),
      this.cells,
      h("div", { class: "bd-battery__cap" }, this.caption, this.delta),
    );
  }

  /** Crea las barras solo si cambió la cantidad de celdas (normalmente, una vez). */
  #ensureCells(n) {
    if (this.cellEls.length === n) return;
    this.cellEls = Array.from({ length: n }, (_, i) => {
      const bar = h("i", { class: "bd-cell__bar" });
      const v = h("span", { class: "bd-cell__v bd-num" }, "—");
      const el = h("div", { class: "bd-cell", role: "listitem", title: `Celda ${i + 1}` },
        h("span", { class: "sr-only" }, `Celda ${i + 1}: `),
        h("span", { class: "bd-cell__track", "aria-hidden": "true" }, bar), v, h("span", { class: "sr-only" }, " V"));
      return { el, bar, v, low: false };
    });
    this.cells.replaceChildren(...this.cellEls.map((c) => c.el));
    this.cells.dataset.count = String(n);
  }

  update(frame) {
    const { bms, derived } = frame;
    setText(this.soc, fmt(bms.soc, 0));
    this.soc.parentElement.dataset.level = socLevel(bms.soc);
    setText(this.current, milliamps(bms.corriente));
    setText(this.sense, currentSense(bms.corriente));
    setText(this.temp, bms.temperatura ? `${fmt(bms.temperatura, 1)} °C` : "—");

    const n = bms.celdas.length;
    this.#ensureCells(n);
    if (!n) {
      // La API de ejemplo trae `celdas: []`: se dice en lugar de mostrar un hueco.
      setText(this.pack, "—");
      setText(this.caption, "El robot no informa la tensión de las celdas");
      setText(this.delta, "");
      return;
    }
    setText(this.pack, `${fmt(derived.packVoltage, 2)} V`);
    const unbalanced = derived.cellDeltaMv > CELL_DELTA_WARN_MV;
    bms.celdas.forEach((v, i) => {
      const c = this.cellEls[i];
      c.bar.style.transform = `scaleY(${clamp((v - CELL_MIN_V) / (CELL_MAX_V - CELL_MIN_V), 0.05, 1).toFixed(3)})`;
      setText(c.v, fmt(v, 3));
      const low = unbalanced && v === derived.cellMin;
      if (low !== c.low) {
        c.low = low;
        c.el.classList.toggle("is-low", low);
      }
    });
    setText(this.caption, `${n} celdas · ${fmt(derived.cellMin, 3)}–${fmt(derived.cellMax, 3)} V`);
    setText(this.delta, `Δ ${derived.cellDeltaMv} mV`);
  }
}

frontend/js/views/body/callouts.js.source:
/**
 * Tarjetas unidas a las articulaciones con una línea (callouts de lámina técnica).
 *
 * - Go2: una tarjeta por motor (temperatura + torque), agrupadas por pata en
 *   las cuatro esquinas, y el estado de apoyo de la pata en el título.
 * - G1: 29 tarjetas no entran; se agrupan con `motorGroup` (brazos, piernas,
 *   torso) en filas compactas, y la línea va al centro de cada grupo.
 *
 * Las posiciones de las tarjetas se miden solo cuando cambia el layout
 * (`measure`); en cada muestra se mueven los extremos de las líneas con la
 * proyección que calcula RobotFigure, sin leer el DOM.
 */
import { h, s, setText, fmt, clamp } from "../../ui/dom.js";
import { tempLevel, motorGroup, LEG_LABELS } from "../../core/telemetryModel.js";

/** "Delantera izquierda" → "Delantera izq." para que entre en la tarjeta. */
const shortLeg = (leg) => LEG_LABELS[leg].replace("izquierda", "izq.").replace("derecha", "der.");

/**
 * Nombre corto para las filas del G1: el grupo ya dice el lado, así que
 * "L_shoulder_pitch" → "sh_pitch". El nombre completo queda en el title.
 */
const shortJoint = (n) => n.replace(/^[LR]_|^torso_/, "").replace("shoulder", "sh").replace("wrist", "wr").replace("ankle", "ank");

export class Callouts {
  /**
   * @param {{ figure: import("./robotFigure.js").RobotFigure, onSelect: Function, torqueScale: () => number }} opts
   */
  constructor({ figure, onSelect, torqueScale }) {
    this.figure = figure;
    this.onSelect = onSelect;
    this.torqueScale = torqueScale;
    this.cards = new Map();    // nombre → { el, temp, tq, bar, level }
    this.legStatus = new Map(); // pata → { el, down }
    this.leaders = [];          // { line, el, side, joint, x1, y1, ox, oy }
    this.colL = h("div", { class: "bd-col bd-col--l" });
    this.colR = h("div", { class: "bd-col bd-col--r" });
    this.lines = s("svg", { class: "bd-leaders", "aria-hidden": "true" });
    this.selectedLine = s("line", { class: "bd-leader bd-leader--selected" });
  }

  /** Los nodos que la vista inserta en el escenario. */
  get nodes() {
    return [this.lines, this.colL, this.colR];
  }

  build(info, kind) {
    this.cards.clear();
    this.legStatus.clear();
    this.leaders = [];
    this.colL.replaceChildren();
    this.colR.replaceChildren();
    this.lines.replaceChildren();
    this.kind = kind;
    this.colL.dataset.kind = this.colR.dataset.kind = kind;
    const names = info?.motores_nombres ?? [];

    if (kind === "quad") {
      // Izquierda de la pantalla = patas izquierdas; arriba = delanteras.
      for (const leg of ["FL", "RL", "FR", "RR"].filter((l) => info.patas.includes(l))) {
        const own = names.filter((n) => n.startsWith(`${leg}_`));
        // En las delanteras la pantorrilla va arriba: así las líneas no se cruzan.
        if (leg[0] === "F") own.reverse();
        const col = leg[1] === "L" ? this.colL : this.colR;
        col.append(this.#group(`${leg} · ${shortLeg(leg)}`, leg, own, "card"));
        for (const n of own) this.#leader(this.cards.get(n).el, leg[1] === "L" ? "l" : "r", n);
      }
    } else if (kind === "humanoid") {
      // De frente: el lado derecho del robot queda a la izquierda de la pantalla.
      const groups = new Map();
      for (const n of names) {
        const g = motorGroup(n);
        if (!groups.has(g.key)) groups.set(g.key, { ...g, names: [] });
        groups.get(g.key).names.push(n);
      }
      // Brazos arriba y piernas abajo, como en el dibujo: así las líneas no se cruzan.
      const place = { R_brazo: "l", R_pierna: "l", torso: "r", L_brazo: "r", L_pierna: "r" };
      const rank = ["R_brazo", "R_pierna", "torso", "L_brazo", "L_pierna"];
      const sorted = [...groups.values()].sort((a, b) => (rank.indexOf(a.key) + 1 || 99) - (rank.indexOf(b.key) + 1 || 99));
      for (const g of sorted) {
        const side = place[g.key] ?? "r";
        const foot = g.key.endsWith("_pierna") ? `${g.key[0]}_foot` : null;
        const el = this.#group(g.label, foot && info.patas?.includes(foot) ? foot : null, g.names, "row");
        (side === "l" ? this.colL : this.colR).append(el);
        // Una línea por grupo, al motor del medio (codo, rodilla, torso).
        this.#leader(el.querySelector(".bd-group__title"), side, g.names[Math.floor(g.names.length / 2)]);
      }
    }
    this.lines.append(this.selectedLine);
  }

  #group(title, leg, names, variant) {
    const status = leg ? h("span", { class: "bd-group__status" }, "—") : null;
    if (leg) this.legStatus.set(leg, { el: status, down: null });
    const el = h("section", { class: `bd-group bd-group--${variant}` },
      h("h3", { class: "bd-group__title" }, h("span", {}, title), status));
    for (const n of names) {
      const temp = h("span", { class: "bd-card__temp" }, "—");
      const tq = h("span", { class: "bd-card__tq" }, "—");
      const bar = h("i");
      const card = h(
        "button",
        { type: "button", class: `bd-card bd-card--${variant}`, "data-level": "ok", title: `${n}: ver el detalle`, onclick: () => this.onSelect(n) },
        h("span", { class: "bd-card__name" }, variant === "row" ? shortJoint(n) : n),
        temp,
        h("span", { class: "bd-card__q" }, h("span", { class: "bd-bar", "aria-hidden": "true" }, bar), tq),
      );
      el.append(card);
      this.cards.set(n, { el: card, temp, tq, bar, level: "ok", torque: null });
    }
    return el;
  }

  #leader(el, side, joint) {
    const line = s("line", { class: "bd-leader" });
    this.lines.append(line);
    this.leaders.push({ line, el, side, joint, x1: 0, y1: 0, x2: null, y2: null });
  }

  setSelected(name) {
    this.selected = name;
    for (const [n, c] of this.cards) c.el.classList.toggle("is-selected", n === name);
    this.#placeSelectedLine();
  }

  /**
   * Mide dónde quedaron las tarjetas y el dibujo. Solo al cambiar el
   * layout (ResizeObserver), nunca en cada muestra.
   * @param {HTMLElement} stage
   */
  measure(stage) {
    const sr = stage.getBoundingClientRect();
    const rr = this.figure.el.getBoundingClientRect();
    this.origin = [rr.left - sr.left, rr.top - sr.top];
    this.visible = this.colL.offsetParent !== null && sr.width > 0;
    this.lines.style.display = this.visible ? "" : "none";
    if (!this.visible) return;
    for (const L of this.leaders) {
      const r = L.el.getBoundingClientRect();
      L.x1 = (L.side === "l" ? r.right : r.left) - sr.left;
      L.y1 = r.top + r.height / 2 - sr.top;
      L.line.setAttribute("x1", L.x1.toFixed(1));
      L.line.setAttribute("y1", L.y1.toFixed(1));
      L.x2 = null; // obliga a recolocar el otro extremo
    }
    this.#measureSelected(sr);
    this.placeLines();
  }

  /** En el G1 la tarjeta elegida también se une a su articulación. */
  #measureSelected(sr = this.lines.getBoundingClientRect()) {
    const card = this.kind === "humanoid" && this.cards.get(this.selected);
    if (!card || !this.visible) { this.sel = null; return; }
    const r = card.el.getBoundingClientRect();
    const left = card.el.closest(".bd-col--l") !== null;
    this.sel = { x1: (left ? r.right : r.left) - sr.left, y1: r.top + r.height / 2 - sr.top };
  }

  #placeSelectedLine() {
    this.#measureSelected();
    const p = this.sel && this.figure.project(this.selected);
    this.selectedLine.style.display = p ? "" : "none";
    if (!p) return;
    this.selectedLine.setAttribute("x1", this.sel.x1.toFixed(1));
    this.selectedLine.setAttribute("y1", this.sel.y1.toFixed(1));
    this.selectedLine.setAttribute("x2", (this.origin[0] + p[0]).toFixed(1));
    this.selectedLine.setAttribute("y2", (this.origin[1] + p[1]).toFixed(1));
  }

  /** Mueve el extremo de cada línea a la articulación (que se inclina con la IMU). */
  placeLines() {
    if (!this.visible || !this.origin) return;
    for (const L of this.leaders) {
      const p = this.figure.project(L.joint);
      if (!p) continue;
      const x2 = this.origin[0] + p[0];
      const y2 = this.origin[1] + p[1];
      if (L.x2 !== null && Math.abs(x2 - L.x2) < 0.3 && Math.abs(y2 - L.y2) < 0.3) continue;
      L.x2 = x2;
      L.y2 = y2;
      L.line.setAttribute("x2", x2.toFixed(1));
      L.line.setAttribute("y2", y2.toFixed(1));
    }
    if (this.sel) {
      const p = this.figure.project(this.selected);
      if (p) {
        this.selectedLine.setAttribute("x2", (this.origin[0] + p[0]).toFixed(1));
        this.selectedLine.setAttribute("y2", (this.origin[1] + p[1]).toFixed(1));
      }
    }
  }

  update(frame) {
    const scale = this.torqueScale();
    for (const m of frame.motores) {
      const c = this.cards.get(m.nombre);
      if (!c) continue;
      const level = tempLevel(m.temperatura);
      if (level !== c.level) {
        c.level = level;
        c.el.dataset.level = level;
        const L = this.leaders.find((x) => x.joint === m.nombre);
        if (L) L.line.classList.toggle("is-hot", level === "crit");
      }
      setText(c.temp, `${fmt(m.temperatura, 1)} °C`);
      setText(c.tq, `${fmt(m.torque, 1)} N·m`);
      const k = clamp(Math.abs(m.torque) / scale, 0, 1);
      if (c.torque === null || Math.abs(k - c.torque) > 0.004) {
        c.torque = k;
        c.bar.style.transform = `scaleX(${k.toFixed(3)})`;
      }
    }
    for (const [leg, st] of this.legStatus) {
      const down = frame.fuerzas[leg] === 1;
      if (down === st.down) continue;
      st.down = down;
      setText(st.el, down ? (leg.endsWith("_foot") ? "pie apoyado" : "apoyada") : "en el aire");
      st.el.dataset.down = String(down);
    }
    this.placeLines();
  }
}

frontend/js/views/body/detailPanel.js.source:
/**
 * La articulación elegida: sus cuatro magnitudes en grande y la curva de su
 * temperatura con los umbrales del semáforo (40 y 60 °C) marcados.
 */
import { h, setText, fmt } from "../../ui/dom.js";
import { tempLevel, motorGroup, jointLabel, TEMP_THRESHOLDS } from "../../core/telemetryModel.js";
import { icon } from "../../ui/icons.js";

/** Muestras de la curva de temperatura (≈ 30 s a 10 Hz). */
const SPARK_SAMPLES = 300;

export class DetailPanel {
  constructor() {
    const value = (cls = "") => h("span", { class: `bd-detail__v bd-num ${cls}` }, "—");
    const unit = (u) => h("small", {}, u);
    this.name = h("span", {}, "—");
    this.where = h("small", {}, "");
    this.temp = value("bd-detail__v--big");
    this.ang = value();
    this.vel = value();
    this.tq = value();
    this.canvas = h("canvas", { class: "bd-spark", role: "img", "aria-label": "Temperatura de la articulación elegida en los últimos 30 segundos" });
    const cell = (k, v, u) => h("div", {}, h("div", { class: "bd-detail__k" }, k), h("div", {}, v, unit(u)));
    this.el = h(
      "section",
      { class: "bd-detail", "aria-labelledby": "bd-detail-title", "aria-live": "off" },
      h("h2", { class: "bd-eyebrow", id: "bd-detail-title", html: `${icon("cpu", { size: 14 })}<span>Articulación elegida</span>` }),
      h("p", { class: "bd-detail__name" }, this.name, this.where),
      h("div", { class: "bd-detail__grid" },
        cell("Temperatura", this.temp, "°C"),
        cell("Ángulo", this.ang, "°"),
        cell("Velocidad", this.vel, "rad/s"),
        cell("Torque", this.tq, "N·m")),
      this.canvas,
    );
    this.level = null;
  }

  /** @param {string} name  @param {number} index posición del motor en `frame.motores` */
  select(name, index) {
    this.selected = name;
    this.index = index;
    setText(this.name, name ?? "—");
    if (!name) return setText(this.where, "");
    const g = motorGroup(name);
    const part = jointLabel(name);
    setText(this.where, [g.key === "otros" ? null : g.label.replace(/^\w+ · /, ""), part].filter(Boolean).join(" · ").toLowerCase());
  }

  /** Busca el motor por posición y, si no coincide, por nombre. */
  #motor(frame) {
    const m = frame.motores[this.index];
    return m?.nombre === this.selected ? m : frame.motores.find((x) => x.nombre === this.selected);
  }

  /**
   * @param {object} frame
   * @param {object[]} history  muestras recientes en orden cronológico
   * @param {Record<string,string>} palette colores ya resueltos del tema
   */
  update(frame, history, palette) {
    const m = this.#motor(frame);
    if (!m) return;
    const level = tempLevel(m.temperatura);
    if (level !== this.level) {
      this.level = level;
      this.temp.dataset.level = level;
    }
    setText(this.temp, fmt(m.temperatura, 1));
    setText(this.ang, fmt(m.angulo, 1));
    setText(this.vel, fmt(m.velocidad, 2));
    setText(this.tq, fmt(m.torque, 1));
    this.#spark(history.slice(-SPARK_SAMPLES), palette);
  }

  #spark(frames, P) {
    const c = this.canvas;
    const dpr = window.devicePixelRatio || 1;
    const W = c.clientWidth;
    const H = c.clientHeight;
    if (!W || !H) return;
    if (c.width !== Math.round(W * dpr) || c.height !== Math.round(H * dpr)) {
      c.width = Math.round(W * dpr);
      c.height = Math.round(H * dpr);
    }
    const x = c.getContext("2d");
    x.setTransform(dpr, 0, 0, dpr, 0, 0);
    x.clearRect(0, 0, W, H);

    const vals = [];
    for (const f of frames) {
      const m = f.motores[this.index]?.nombre === this.selected ? f.motores[this.index] : null;
      if (m) vals.push(m.temperatura);
    }
    // Escala que siempre muestra las dos líneas del semáforo y la curva entera.
    const lo = Math.min(25, ...vals) - 1;
    const hi = Math.max(70, ...vals) + 1;
    const right = W - 44; // lugar para los rótulos de los umbrales
    const Y = (v) => H - 3 - ((v - lo) / (hi - lo)) * (H - 6);

    x.font = `11px ${P.mono}`;
    x.textBaseline = "middle";
    x.setLineDash([3, 3]);
    x.lineWidth = 1;
    for (const [t, color] of [[TEMP_THRESHOLDS.warn, P.warn], [TEMP_THRESHOLDS.crit, P.crit]]) {
      x.strokeStyle = color;
      x.globalAlpha = 0.6;
      x.beginPath();
      x.moveTo(0, Y(t));
      x.lineTo(right, Y(t));
      x.stroke();
      x.globalAlpha = 1;
      x.fillStyle = P.muted;
      x.fillText(`${t} °C`, right + 6, Y(t));
    }
    x.setLineDash([]);
    if (vals.length < 2) return;
    x.strokeStyle = this.level === "crit" ? P.crit : P.ink;
    x.lineWidth = 1.8;
    x.lineJoin = "round";
    x.beginPath();
    // Anclada a la derecha ("ahora"): con pocas muestras la curva arranca a mitad de camino.
    const offset = SPARK_SAMPLES - vals.length;
    vals.forEach((v, i) => {
      const px = ((offset + i) / (SPARK_SAMPLES - 1)) * right;
      i ? x.lineTo(px, Y(v)) : x.moveTo(px, Y(v));
    });
    x.stroke();
  }
}

frontend/js/views/body/format.js.source:
/**
 * Formatos propios de la vista Cuerpo. Los genéricos (fmt, clamp) están en
 * ui/dom.js; acá van solo los que necesitan un criterio de esta vista.
 */
import { fmt } from "../../ui/dom.js";

const DIRS = ["N", "NE", "E", "SE", "S", "SO", "O", "NO"];

/** Lleva cualquier ángulo a [0, 360). El yaw puede llegar como −180…180. */
export const wrap360 = (deg) => ((deg % 360) + 360) % 360;

/** Punto cardinal más cercano a un rumbo: 337° → "NO", 338° → "N". */
export const cardinal = (deg) => DIRS[Math.round(wrap360(deg) / 45) % 8];

/**
 * Corriente en mA con separador de miles fino ("4 201 mA"). Se evita el
 * punto de miles del castellano porque el resto del tablero usa punto
 * decimal y "4.201" se leería como cuatro amperes.
 */
export function milliamps(value) {
  if (!Number.isFinite(value)) return "—";
  const rounded = Math.round(Math.abs(value));
  const abs = rounded.toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  // Sin «−0 mA»: el signo va solo si el valor redondeado no es cero (spec 010 · FR-005).
  return `${value < 0 && rounded > 0 ? "−" : ""}${abs} mA`;
}

/**
 * Sentido de la corriente. La API la entrega POSITIVA al descargar (el
 * robot consume); negativa significa que entra carga.
 */
export function currentSense(value) {
  if (!Number.isFinite(value) || Math.abs(value) < 1) return "en reposo";
  return value > 0 ? "descargando" : "cargando";
}

/** Grados con signo y un decimal: −2.1° */
export const degrees = (v, decimals = 1) => `${fmt(v, decimals, { sign: true }).trim()}°`;

frontend/js/views/body/motorTable.js.source:
/**
 * Tabla de todos los motores (panel de motores de la consigna): temperatura
 * con semáforo, ángulo, velocidad y torque.
 *
 * Las filas se crean una vez por robot. En cada muestra solo cambian textos y,
 * si se ordena por temperatura, el orden (se mueven las filas existentes, no se
 * recrean). Por defecto se agrupan por pata o por parte del cuerpo, en el
 * orden de los ids, como pide la consigna.
 */
import { h, setText, fmt } from "../../ui/dom.js";
import { tempLevel, motorGroup } from "../../core/telemetryModel.js";

export class MotorTable {
  /** @param {{ onSelect: (name: string) => void }} opts */
  constructor({ onSelect }) {
    this.onSelect = onSelect;
    this.rows = new Map(); // nombre → { tr, temp, ang, vel, tq, level }
    this.sortByTemp = false;
    this.order = "";

    this.sortBtn = h("button", { type: "button", class: "bd-linkbtn", "aria-pressed": "false", onclick: () => this.toggleSort() }, "ordenar por temperatura");
    this.count = h("span", { class: "bd-sub" });
    this.tbody = h("tbody");
    this.tbody.addEventListener("click", (e) => {
      const tr = e.target.closest("tr[data-name]");
      if (tr) this.onSelect(tr.dataset.name);
    });
    // Unidad en una segunda línea: la tabla entra en 400 px aun con los nombres largos del G1.
    const th = (text, cls, title, unit) => h("th", { scope: "col", class: cls, title }, text, unit ? h("small", {}, unit) : null);
    this.el = h(
      "section",
      { class: "bd-motors", "aria-labelledby": "bd-motors-title" },
      h("header", { class: "bd-panel-head" },
        h("h2", { class: "bd-eyebrow", id: "bd-motors-title" }, "Motores"),
        this.count,
        h("span", { class: "bd-spacer" }),
        this.sortBtn),
      h("div", { class: "bd-motors__scroll" },
        h("table", { class: "bd-table" },
          h("caption", { class: "sr-only" }, "Temperatura, ángulo, velocidad y torque de cada motor"),
          h("thead", {}, h("tr", {},
            th("Motor", "bd-l"),
            th("Temp.", "", "Temperatura del motor: verde < 40 °C, amarillo 40–60 °C, rojo > 60 °C", "°C"),
            th("Ángulo", "", "Ángulo de la articulación en grados", "°"),
            th("Vel.", "", "Velocidad angular en radianes por segundo", "rad/s"),
            th("Torque", "", "Torque estimado en newton·metro", "N·m"))),
          this.tbody)),
    );
  }

  build(info) {
    this.rows.clear();
    this.order = "";
    const names = info?.motores_nombres ?? [];
    setText(this.count, `· ${names.length} motores`);
    const frag = [];
    let lastGroup = null;
    for (const n of names) {
      const g = motorGroup(n);
      if (g.key !== lastGroup) {
        lastGroup = g.key;
        frag.push(h("tr", { class: "bd-table__group" }, h("th", { colspan: "5", scope: "rowgroup" }, g.label)));
      }
      const temp = h("span", { class: "bd-num" }, "—");
      const cells = {
        temp,
        ang: h("td", { class: "bd-num" }, "—"),
        vel: h("td", { class: "bd-num" }, "—"),
        tq: h("td", { class: "bd-num" }, "—"),
      };
      const tr = h(
        "tr",
        { "data-name": n, "data-level": "ok" },
        h("th", { scope: "row", class: "bd-l" }, h("button", { type: "button", class: "bd-rowbtn", "aria-label": `Ver detalle de ${n}` }, n)),
        h("td", { class: "bd-table__temp" }, h("i", { class: "bd-dot", "aria-hidden": "true" }), temp),
        cells.ang, cells.vel, cells.tq,
      );
      frag.push(tr);
      this.rows.set(n, { tr, ...cells, level: "ok" });
    }
    this.groupRows = frag.filter((r) => r.classList.contains("bd-table__group"));
    this.initialOrder = frag;
    this.tbody.replaceChildren(...frag);
    this.#applySortMode();
  }

  toggleSort() {
    this.sortByTemp = !this.sortByTemp;
    this.#applySortMode();
    if (this.last) this.update(this.last);
  }

  #applySortMode() {
    this.sortBtn.setAttribute("aria-pressed", String(this.sortByTemp));
    setText(this.sortBtn, this.sortByTemp ? "ordenar por grupo" : "ordenar por temperatura");
    this.order = "";
    for (const g of this.groupRows ?? []) g.hidden = this.sortByTemp;
    if (!this.sortByTemp && this.initialOrder) this.tbody.append(...this.initialOrder);
  }

  setSelected(name) {
    for (const [n, r] of this.rows) r.tr.classList.toggle("is-selected", n === name);
  }

  /** Lleva la fila elegida a la vista (al elegir desde el dibujo). */
  reveal(name) {
    this.rows.get(name)?.tr.scrollIntoView({ block: "nearest" });
  }

  update(frame) {
    this.last = frame;
    for (const m of frame.motores) {
      const r = this.rows.get(m.nombre);
      if (!r) continue;
      const level = tempLevel(m.temperatura);
      if (level !== r.level) {
        r.level = level;
        r.tr.dataset.level = level;
      }
      setText(r.temp, fmt(m.temperatura, 1));
      setText(r.ang, fmt(m.angulo, 1));
      setText(r.vel, fmt(m.velocidad, 2));
      setText(r.tq, fmt(m.torque, 1));
    }
    if (this.sortByTemp) {
      // Se reordena solo si el orden cambió (evita mover nodos 10 veces por segundo).
      const sorted = [...frame.motores].sort((a, b) => b.temperatura - a.temperatura).map((m) => m.nombre);
      const key = sorted.join(",");
      if (key !== this.order) {
        this.order = key;
        this.tbody.append(...sorted.map((n) => this.rows.get(n)?.tr).filter(Boolean));
      }
    }
  }
}

