/**
 * El robot dibujado como interfaz (SVG).
 *
 * - Go2 (cuadrúpedo): visto desde arriba; cada pata sale de su esquina.
 * - G1 (humanoide): visto de frente, con brazos, torso y piernas.
 * - Cualquier otro: un cuerpo con las articulaciones en ronda (para no romper
 *   si mañana aparece un robot con otros nombres).
 *
 * Todo sale de `info.motores_nombres` e `info.patas`: nada de 12 motores fijos.
 * El SVG se arma UNA vez por robot (en `build`); `update` solo cambia
 * atributos, clases y `transform`.
 *
 * Convención de la IMU (la de ROS / Unitree, la que usa el simulador):
 * roll > 0 baja el lado derecho; pitch > 0 baja la nariz; yaw > 0 es un giro
 * a la izquierda (antihorario visto desde arriba).
 */
import { h, s, setText, fmt } from "../../ui/dom.js";
import { tempLevel, socLevel } from "../../core/telemetryModel.js";

/** Exageración de la inclinación: 1–2° reales no se verían. */
export const TILT_GAIN = 3;
/** Distancia de la cámara para la perspectiva 3D (px), igual a la del CSS. */
const PERSPECTIVE = 900;
/** El viewBox es un cuadrado centrado en 0,0; el anillo de rumbo tiene radio 200. */
const VB = 430;
const RING_R = 200;

/* ------------------------------------------------------------------ */
/* Geometría                                                           */
/* ------------------------------------------------------------------ */

/** Pata del Go2 vista desde arriba: cadera, muslo, pantorrilla y pie. */
function quadLeg(leg) {
  const sx = leg[1] === "R" ? 1 : -1;  // pata derecha → a la derecha de la pantalla
  const sy = leg[0] === "F" ? -1 : 1;  // delantera → arriba (el robot mira hacia arriba)
  const p = (x, y) => [x * sx, y * sy];
  return { path: [p(42, 85), p(80, 105), p(104, 137)], foot: p(118, 161) };
}

/**
 * Humanoide de frente: el lado izquierdo del robot queda a la DERECHA de la
 * pantalla (como cuando lo tenés enfrente). Coordenadas del lado izquierdo.
 */
const HUMANOID_JOINTS = {
  shoulder_pitch: [62, -108], shoulder_roll: [70, -92], shoulder_yaw: [75, -74], elbow: [80, -42],
  wrist_roll: [85, -10], wrist_pitch: [88, 6], wrist_yaw: [90, 22],
  hip_yaw: [20, 54], hip_roll: [24, 68], hip_pitch: [27, 82], knee: [31, 116],
  ankle_pitch: [34, 146], ankle_roll: [36, 160],
};
const TORSO_JOINTS = { torso_yaw: [-14, 32], torso_roll: [0, 32], torso_pitch: [14, 32] };

function humanoidPoint(name) {
  if (TORSO_JOINTS[name]) return TORSO_JOINTS[name];
  const m = /^([LR])_(.+)$/.exec(name);
  const base = m && HUMANOID_JOINTS[m[2]];
  if (!base) return null;
  return [m[1] === "L" ? base[0] : -base[0], base[1]];
}

/** Interpola un punto a lo largo de una poligonal (t de 0 a 1). */
function along(points, t) {
  const seg = [];
  let total = 0;
  for (let i = 1; i < points.length; i++) {
    const d = Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1]);
    seg.push(d);
    total += d;
  }
  // Avanza tramo por tramo hasta el que contiene la distancia (o el último).
  let dist = t * total;
  let i = 0;
  while (i < seg.length - 1 && dist > seg[i]) dist -= seg[i++];
  const k = Math.min(1, dist / seg[i]);
  return [points[i][0] + (points[i + 1][0] - points[i][0]) * k, points[i][1] + (points[i + 1][1] - points[i][1]) * k];
}

/** Qué cuerpo dibujar según lo que informa /info. */
export function bodyKind(info) {
  const legs = info?.patas ?? [];
  if (legs.some((l) => /^[FR][LR]$/.test(l))) return "quad";
  if (info?.tipo === "humanoide" || legs.some((l) => l.endsWith("_foot"))) return "humanoid";
  return "generic";
}

/* ------------------------------------------------------------------ */
/* Matemática de la inclinación                                        */
/* ------------------------------------------------------------------ */

const rad = (d) => (d * Math.PI) / 180;
const ROT = {
  x: (a) => [[1, 0, 0], [0, Math.cos(a), -Math.sin(a)], [0, Math.sin(a), Math.cos(a)]],
  y: (a) => [[Math.cos(a), 0, Math.sin(a)], [0, 1, 0], [-Math.sin(a), 0, Math.cos(a)]],
  z: (a) => [[Math.cos(a), -Math.sin(a), 0], [Math.sin(a), Math.cos(a), 0], [0, 0, 1]],
};
const mul = (A, B) => A.map((row) => [0, 1, 2].map((j) => row[0] * B[0][j] + row[1] * B[1][j] + row[2] * B[2][j]));

/**
 * Rotaciones (en el orden de CSS) a partir de roll y pitch. Devuelve el
 * string para `style.transform` y la matriz equivalente, que se usa para
 * saber dónde quedó cada articulación en pantalla SIN leer el layout.
 */
function tiltFor(kind, roll, pitch, gain) {
  const steps = kind === "humanoid"
    // De frente: el roll es una inclinación en el plano (lado derecho del robot = izquierda de la pantalla);
    // el pitch acerca o aleja la cabeza.
    ? [["x", -pitch * gain], ["z", -roll * gain]]
    // Desde arriba: la nariz baja (pitch > 0) → el frente se aleja; el lado derecho baja (roll > 0) → se aleja.
    : [["x", pitch * gain], ["y", roll * gain]];
  const css = steps.map(([axis, deg]) => `rotate${axis.toUpperCase()}(${deg.toFixed(2)}deg)`).join(" ");
  const matrix = steps.reduce((M, [axis, deg]) => mul(M, ROT[axis](rad(deg))), ROT.z(0));
  return { css, matrix };
}

/* ------------------------------------------------------------------ */
/* Figura                                                              */
/* ------------------------------------------------------------------ */

export class RobotFigure {
  /** @param {{ onSelect: (name: string) => void }} opts */
  constructor({ onSelect }) {
    this.onSelect = onSelect;
    this.joints = new Map();   // nombre → { g, x, y, level }
    this.feet = new Map();     // pata → { foot, ripple, down }
    this.matrix = ROT.z(0);
    this.sizePx = 0;

    this.shadow = h("div", { class: "bd-shadow", "aria-hidden": "true" });
    this.svg = s("svg", { class: "bd-robot", viewBox: `${-VB / 2} ${-VB / 2} ${VB} ${VB}`, role: "group" });
    this.tilt = h("div", { class: "bd-tilt" }, this.svg);
    this.el = h("div", { class: "bd-robotbox" }, this.shadow, this.tilt);
  }

  /** Arma el dibujo para un robot. Se llama en setInfo (no en cada muestra). */
  build(info) {
    this.kind = bodyKind(info);
    this.el.dataset.kind = this.kind;
    this.joints.clear();
    this.feet.clear();
    this.svg.replaceChildren();
    this.svg.setAttribute("aria-label", this.kind === "humanoid"
      ? "Robot humanoide visto de frente: cada punto es un motor con el color de su temperatura"
      : "Robot visto desde arriba: cada punto es un motor con el color de su temperatura");

    this.#buildRing();
    const names = info?.motores_nombres ?? [];
    const placed = this.kind === "quad" ? this.#buildQuad(info, names)
      : this.kind === "humanoid" ? this.#buildHumanoid(info, names)
        : this.#buildGeneric();

    // Los motores que el dibujo no sabe ubicar van en ronda alrededor del cuerpo:
    // así ningún motor queda sin su punto, aunque cambien los nombres.
    const orphans = names.filter((n) => !placed.has(n));
    orphans.forEach((n, i) => {
      const a = (i / orphans.length) * 2 * Math.PI - Math.PI / 2;
      placed.set(n, [Math.cos(a) * 160, Math.sin(a) * 160]);
    });
    const r = this.kind === "humanoid" ? 6 : 8.5;
    for (const n of names) this.#addJoint(n, placed.get(n), /_hip$/.test(n) ? r - 1 : r);
  }

  #buildRing() {
    // El anillo gira con el yaw; el robot queda siempre mirando hacia arriba.
    this.ring = s("g", { class: "bd-ring" });
    this.ring.append(s("circle", { r: RING_R, class: "bd-ring__circle" }));
    for (let a = 0; a < 360; a += 10) {
      const r1 = a % 90 === 0 ? RING_R - 12 : a % 30 === 0 ? RING_R - 8 : RING_R - 5;
      const t = rad(a);
      this.ring.append(s("line", {
        x1: Math.sin(t) * r1, y1: -Math.cos(t) * r1, x2: Math.sin(t) * RING_R, y2: -Math.cos(t) * RING_R,
        class: a % 90 === 0 ? "bd-ring__tick bd-ring__tick--major" : "bd-ring__tick",
      }));
    }
    for (const [label, a] of [["N", 0], ["E", 90], ["S", 180], ["O", 270]]) {
      const t = rad(a);
      const text = s("text", { x: Math.sin(t) * (RING_R - 26), y: -Math.cos(t) * (RING_R - 26) + 4, class: label === "N" ? "bd-ring__label bd-ring__label--north" : "bd-ring__label" });
      text.textContent = label;
      this.ring.append(text);
    }
    // Marca fija arriba: hacia dónde mira el robot.
    this.svg.append(this.ring, s("path", { d: `M0 ${-RING_R - 3} l-7 -10 h14 z`, class: "bd-ring__heading" }));
  }

  /** Cuerpo = batería: un rectángulo que se llena según el SOC. */
  #buildBattery(x, y, w, hgt, rx, textY) {
    const id = `bd-clip-${Math.random().toString(36).slice(2, 8)}`;
    const clip = s("clipPath", { id }, s("rect", { x: x + 2, y: y + 2, width: w - 4, height: hgt - 4, rx: rx - 2 }));
    this.batFill = s("rect", { x, y, width: w, height: hgt, class: "bd-batfill", "clip-path": `url(#${id})` });
    this.batText = s("text", { x: 0, y: textY, class: "bd-battext" });
    this.batSub = s("text", { x: 0, y: textY + 20, class: "bd-batsub" });
    this.batSub.textContent = "batería";
    this.svg.append(
      s("defs", {}, clip),
      s("rect", { x, y, width: w, height: hgt, rx, class: "bd-body" }),
      this.batFill,
    );
    return [this.batText, this.batSub];
  }

  #buildQuad(info, names) {
    const placed = new Map();
    const legsG = s("g", { class: "bd-limbs" });
    this.svg.append(legsG);
    const texts = this.#buildBattery(-54, -117, 108, 236, 30, 4);
    // Cabeza: el frente del robot, para que se lea hacia dónde camina.
    this.svg.append(
      s("path", { d: "M-36 -117c0-22 16-38 36-38s36 16 36 38", class: "bd-body" }),
      s("circle", { cx: -12, cy: -137, r: 4, class: "bd-eye" }),
      s("circle", { cx: 12, cy: -137, r: 4, class: "bd-eye" }),
      ...texts,
    );

    for (const leg of info.patas.filter((l) => /^[FR][LR]$/.test(l))) {
      const geo = quadLeg(leg);
      const pts = [...geo.path, geo.foot];
      legsG.append(s("path", { d: `M${pts.map((p) => p.join(" ")).join(" L")}` }));
      const own = names.filter((n) => n.startsWith(`${leg}_`));
      // Con 3 motores por pata (cadera, muslo, pantorrilla) caen en los codos del dibujo;
      // con otra cantidad se reparten a lo largo de la pata.
      own.forEach((n, i) => placed.set(n, own.length === 3 ? geo.path[i] : along(geo.path, own.length > 1 ? i / (own.length - 1) : 0)));
      this.#addFoot(leg, geo.foot, 13, leg, leg[1] === "R" ? 1 : -1);
    }
    return placed;
  }

  #buildHumanoid(info, names) {
    const placed = new Map();
    const limbs = s("g", { class: "bd-limbs" });
    const arm = (sx) => `M${62 * sx} -108 L${80 * sx} -42 L${92 * sx} 30`;
    const leg = (sx) => `M${20 * sx} 44 L${31 * sx} 116 L${36 * sx} 160 L${46 * sx} 166`;
    limbs.append(s("path", { d: `${arm(1)} ${arm(-1)} ${leg(1)} ${leg(-1)}` }));
    this.svg.append(limbs);
    const texts = this.#buildBattery(-48, -124, 96, 140, 24, -50);
    this.svg.append(
      s("rect", { x: -38, y: 20, width: 76, height: 26, rx: 10, class: "bd-body" }),   // cadera
      s("circle", { cx: 0, cy: -154, r: 22, class: "bd-body" }),                        // cabeza
      s("circle", { cx: -8, cy: -156, r: 3, class: "bd-eye" }),
      s("circle", { cx: 8, cy: -156, r: 3, class: "bd-eye" }),
      ...texts,
    );
    for (const n of names) {
      const p = humanoidPoint(n);
      if (p) placed.set(n, p);
    }
    for (const foot of info.patas ?? []) {
      const sx = foot.startsWith("L") ? 1 : -1;
      this.#addFoot(foot, [50 * sx, 170], 10, sx > 0 ? "pie izq." : "pie der.", sx);
    }
    return placed;
  }

  #buildGeneric() {
    const texts = this.#buildBattery(-60, -90, 120, 180, 30, 4);
    this.svg.append(...texts);
    return new Map();
  }

  #addFoot(leg, [x, y], r, label, side) {
    const ripple = s("circle", { cx: x, cy: y, r, class: "bd-ripple" });
    const foot = s("circle", { cx: x, cy: y, r, class: "bd-foot" });
    // El rótulo va hacia afuera del pie (en el G1, más lejos: el texto es más largo).
    const gap = this.kind === "humanoid" ? r + 30 : r + 14;
    const text = s("text", { x: x + side * gap, y: y + 4, class: "bd-foot__label" });
    text.textContent = label;
    const title = s("title");
    title.textContent = leg;
    foot.append(title);
    this.svg.append(ripple, foot, text);
    this.feet.set(leg, { foot, ripple, down: null });
  }

  #addJoint(name, [x, y], r) {
    const g = s("g", { class: "bd-joint", "data-level": "ok", role: "button", tabindex: "-1", "aria-label": `Motor ${name}` });
    g.append(
      s("circle", { cx: x, cy: y, r, class: "bd-joint__pulse" }),
      s("circle", { cx: x, cy: y, r: r + 6, class: "bd-joint__halo" }),
      s("circle", { cx: x, cy: y, r, class: "bd-joint__dot" }),
    );
    g.addEventListener("click", () => this.onSelect(name));
    this.svg.append(g);
    this.joints.set(name, { g, x, y, level: "ok" });
  }

  setSelected(name) {
    for (const [n, j] of this.joints) j.g.classList.toggle("is-selected", n === name);
  }

  /** Tamaño en px del dibujo (lo mide la vista con un ResizeObserver). */
  resize(sizePx) {
    this.sizePx = sizePx;
  }

  /**
   * Dónde está una articulación en pantalla, en px relativos a la esquina del
   * dibujo, aplicando la misma rotación y perspectiva que el CSS. Así las
   * líneas de las tarjetas siguen al robot inclinado sin medir el DOM.
   */
  project(name) {
    const j = this.joints.get(name);
    if (!j || !this.sizePx) return null;
    const k = this.sizePx / VB;
    const p = [j.x * k, j.y * k, 0];
    const M = this.matrix;
    const x = M[0][0] * p[0] + M[0][1] * p[1];
    const y = M[1][0] * p[0] + M[1][1] * p[1];
    const z = M[2][0] * p[0] + M[2][1] * p[1];
    const f = PERSPECTIVE / (PERSPECTIVE - z);
    return [this.sizePx / 2 + x * f, this.sizePx / 2 + y * f];
  }

  /**
   * @param {object} frame
   * @param {{ reducedMotion: boolean }} opts
   */
  update(frame, { reducedMotion }) {
    // Semáforo: la clase cambia solo si cambió el nivel (evita recalcular estilos).
    for (const m of frame.motores) {
      const j = this.joints.get(m.nombre);
      if (!j) continue;
      const level = tempLevel(m.temperatura);
      if (level !== j.level) {
        j.level = level;
        j.g.dataset.level = level;
      }
    }

    // Patas: se rellenan al apoyar y sueltan una onda en el instante del apoyo.
    for (const [leg, f] of this.feet) {
      const down = frame.fuerzas[leg] === 1;
      if (down === f.down) continue;
      f.foot.classList.toggle("is-down", down);
      if (down && f.down === false && !reducedMotion) {
        f.ripple.animate(
          [{ transform: "scale(1)", opacity: 0.6 }, { transform: "scale(2.4)", opacity: 0 }],
          { duration: 500, easing: "ease-out" },
        );
      }
      f.down = down;
    }

    // Batería: el cuerpo se llena con el SOC.
    const soc = Math.max(0, Math.min(100, frame.bms.soc));
    this.batFill.style.transform = `scaleY(${soc / 100})`;
    this.batFill.dataset.level = socLevel(soc);
    setText(this.batText, `${fmt(soc, 0)}%`);

    // IMU: el dibujo se inclina en 3D y el anillo gira con el yaw.
    const gain = reducedMotion ? 0 : TILT_GAIN;
    const { css, matrix } = tiltFor(this.kind, frame.imu.roll, frame.imu.pitch, gain);
    this.matrix = matrix;
    this.tilt.style.transform = css;
    this.shadow.style.transform = `translate(${(frame.imu.roll * gain * 1.4).toFixed(1)}px, ${(frame.imu.pitch * gain * 1.4 + 8).toFixed(1)}px)`;
    // yaw > 0 = giró a la izquierda → el norte queda corrido a su derecha: el anillo gira en sentido horario.
    this.ring.setAttribute("transform", `rotate(${frame.imu.yaw.toFixed(1)})`);
  }
}

frontend/js/views/body/sentence.js.source:
/**
 * La frase de arriba: el estado del robot en lenguaje natural.
 *
 * Es una función pura (muestra → textos) para poder probarla sin DOM. Devuelve
 * cuatro tramos fijos en lugar de HTML: la vista los escribe en cuatro <span>
 * creados una sola vez, así `update()` solo cambia textContent.
 */
import { fmt } from "../../ui/dom.js";
import { tempLevel, TEMP_THRESHOLDS } from "../../core/telemetryModel.js";
import { wrap360 } from "./format.js";

/** Velocidad de giro (°/s) a partir de la cual decimos que "dobla". */
export const TURN_THRESHOLD = 8;

/**
 * Velocidad de giro media en °/s de las últimas muestras. Desenrolla el salto
 * 359° → 0° para que cruzar el norte no parezca un giro de 359°.
 * @param {object[]} frames muestras en orden cronológico (≥ 2)
 */
export function yawRate(frames) {
  if (frames.length < 2) return 0;
  let total = 0;
  for (let i = 1; i < frames.length; i++) {
    let d = wrap360(frames[i].imu.yaw) - wrap360(frames[i - 1].imu.yaw);
    if (d > 180) d -= 360;
    if (d < -180) d += 360;
    total += d;
  }
  const dt = (frames.at(-1).receivedAt - frames[0].receivedAt) / 1000;
  return dt > 0 ? total / dt : 0;
}

/** "4 patas apoyadas", "1 de 2 pies apoyado"… según el robot. */
function contactsText(frame) {
  const { contacts, legs } = frame.derived;
  if (!legs) return "sin datos de contacto";
  // El G1 informa pies (R_foot, L_foot); el Go2, patas. Cambia el género.
  const feet = Object.keys(frame.fuerzas).some((k) => k.endsWith("_foot"));
  const one = contacts === 1;
  const noun = feet ? (one ? "pie" : "pies") : one ? "pata" : "patas";
  const adj = (feet ? "apoyado" : "apoyada") + (one ? "" : "s");
  if (contacts === 0) return feet ? "ningún pie apoyado" : "ninguna pata apoyada";
  if (contacts === legs) {
    const all = { 2: feet ? "los dos" : "las dos", 4: "las cuatro" }[legs] ?? `${feet ? "los" : "las"} ${legs}`;
    return `${all} ${noun} ${adj}`;
  }
  if (one) return feet ? "un solo pie apoyado" : "una sola pata apoyada";
  return `${contacts} de ${legs} ${noun} ${adj}`;
}

/**
 * @param {object} frame   muestra normalizada
 * @param {number} turn    velocidad de giro en °/s (ver yawRate)
 * @returns {{action:string, contacts:string, heat:string, heatLevel:string, battery:string}}
 */
export function describe(frame, turn = 0) {
  const moving = frame.derived.isMoving;
  const turning = Math.abs(turn) > TURN_THRESHOLD;
  const action = moving ? (turning ? "Caminando y doblando" : "Caminando derecho") : turning ? "Girando en el lugar" : "Quieto";

  const hot = frame.motores.filter((m) => m.temperatura > TEMP_THRESHOLDS.crit).sort((a, b) => b.temperatura - a.temperatura);
  const top = frame.derived.tempMax;
  let heat = "";
  let heatLevel = "ok";
  if (hot.length) {
    heatLevel = "crit";
    heat = `${hot[0].nombre} a ${fmt(hot[0].temperatura, 1)} °C`;
    heat += hot.length > 1 ? ` y ${hot.length - 1} más sobre ${TEMP_THRESHOLDS.crit} °C` : ` (más de ${TEMP_THRESHOLDS.crit} °C)`;
  } else if (top) {
    heatLevel = tempLevel(top.value);
    heat = `el más caliente: ${top.motor} a ${fmt(top.value, 1)} °C`;
  }

  return {
    action,
    contacts: contactsText(frame),
    heat,
    heatLevel,
    battery: `batería ${fmt(frame.bms.soc, 0)} %`,
  };
}

frontend/js/views/body/timeline.js.source:
/**
 * Línea de tiempo (canvas): en el mismo eje de tiempo, la inclinación (roll y
 * pitch), el yaw, el diagrama de apoyos y el motor más caliente. Las capturas
 * quedan clavadas como alfileres numerados y la grabación continua, como una
 * franja sombreada.
 *
 * Es el gráfico histórico de la IMU que pide la consigna (≥ 60 muestras, con
 * eje numérico): a 10 Hz muestra 300 muestras. El eje X es el tiempo de
 * llegada (`receivedAt`) y no el índice: con polling o con cortes, los huecos
 * se ven como huecos y las capturas caen donde ocurrieron.
 *
 * Se dibuja en canvas porque son cientos de puntos por pista, 10 veces por
 * segundo: con SVG serían miles de nodos.
 */

/** Ventana visible. */
export const WINDOW_MS = 30_000;
/** Un hueco mayor que esto corta la línea (corte de conexión, pausa del servidor). */
const GAP_MS = 1_500;
/** Escalas "redondas" para roll y pitch: la escala se adapta pero no baila. */
const TILT_STEPS = [2, 5, 10, 15, 20, 30, 45, 60, 90, 180];
/** Orden de dibujo de las patas: como se ven en el dibujo (izquierda primero). */
const LEG_ORDER = ["FL", "FR", "RL", "RR", "R_foot", "L_foot"];

export class Timeline {
  /** @param {HTMLCanvasElement} canvas */
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.tiltScale = TILT_STEPS[1];
  }

  /** Ajusta el tamaño del lienzo a su caja (con la densidad de la pantalla). */
  #fit() {
    const c = this.canvas;
    const dpr = window.devicePixelRatio || 1;
    const W = c.clientWidth;
    const H = c.clientHeight;
    if (c.width !== Math.round(W * dpr) || c.height !== Math.round(H * dpr)) {
      c.width = Math.round(W * dpr);
      c.height = Math.round(H * dpr);
    }
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return [W, H];
  }

  /**
   * @param {object}   o
   * @param {object[]} o.frames    historial en orden cronológico
   * @param {object[]} o.captures  capturas (CaptureStore.samples), en orden cronológico
   * @param {number}   o.now       instante del borde derecho (ms)
   * @param {string[]} o.legs      patas que informa el robot (info.patas)
   * @param {Record<string,string>} o.palette colores del tema
   */
  draw({ frames, captures, now, legs, palette: P }) {
    const [W, H] = this.#fit();
    const x = this.ctx;
    x.clearRect(0, 0, W, H);
    // La cuenta va antes de salir: sin tamaño todavía, la vista igual la muestra (spec 010 · FR-009).
    const t0 = now - WINDOW_MS;
    const visible = frames.filter((f, i) => f.receivedAt >= t0 || frames[i + 1]?.receivedAt >= t0);
    this.count = visible.length;
    if (!W || !H) return;

    const compact = W < 560;
    const titleW = compact ? 0 : 92;   // columna con el nombre de cada pista
    const tickW = 42;                   // columna con los números del eje Y
    const left = titleW + tickW;
    const right = W - 6;
    const top = 16;                     // lugar para la cabeza de los alfileres
    const bottom = H - 18;              // lugar para el eje de tiempo
    const plotW = right - left;
    const X = (t) => right - ((now - t) / WINDOW_MS) * plotW;

    const legList = [...legs].sort((a, b) => LEG_ORDER.indexOf(a) - LEG_ORDER.indexOf(b));
    const tracks = [
      { key: "tilt", title: "Roll · pitch", weight: 0.4 },
      { key: "yaw", title: "Yaw", weight: 0.22 },
      { key: "legs", title: legList.some((l) => l.endsWith("_foot")) ? "Pies" : "Patas", weight: legList.length ? 0.075 * legList.length + 0.03 : 0.1 },
      { key: "heat", title: "Más caliente", weight: 0.1 },
    ];
    const gap = 6;
    const avail = bottom - top - gap * (tracks.length - 1);
    const sum = tracks.reduce((a, t) => a + t.weight, 0);
    let y = top;

    x.textBaseline = "middle";
    for (const t of tracks) {
      const th = (avail * t.weight) / sum;
      const box = { y, h: th };
      x.fillStyle = P.track;
      x.fillRect(left, y, plotW, th);
      if (!compact) {
        x.font = `600 12px ${P.sans}`;
        x.fillStyle = P.muted;
        x.textAlign = "left";
        x.fillText(t.title, 0, y + Math.min(th / 2, 9));
      }
      if (t.key === "tilt") this.#tilt(visible, box, { X, left, right, compact, P });
      else if (t.key === "yaw") this.#yaw(visible, box, { X, left, right, compact, P });
      else if (t.key === "legs") this.#legs(visible, legList, box, { X, left, right, now, P });
      else this.#heat(visible, box, { X, left, right, compact, now, P });
      y += th + gap;
    }

    this.#captures(captures, { X, t0, top, bottom, now, P });
    this.#timeAxis({ left, right, plotW, H, P, compact });
  }

  /** Título dentro de la pista (en el celular no hay columna de títulos). */
  #inlineTitle(text, box, left, P) {
    const x = this.ctx;
    x.font = `600 11px ${P.sans}`;
    x.textAlign = "left";
    x.fillStyle = P.muted;
    x.fillText(text, left + 6, box.y + 8);
  }

  /** Números del eje Y, alineados a la derecha de su columna. */
  #tick(text, y, left, P, size = 11) {
    const x = this.ctx;
    x.font = `${size}px ${P.mono}`;
    x.fillStyle = P.muted;
    x.textAlign = "right";
    x.fillText(text, left - 6, y);
  }

  #hline(y, left, right, color, dash = []) {
    const x = this.ctx;
    x.strokeStyle = color;
    x.lineWidth = 1;
    x.setLineDash(dash);
    x.beginPath();
    x.moveTo(left, Math.round(y) + 0.5);
    x.lineTo(right, Math.round(y) + 0.5);
    x.stroke();
    x.setLineDash([]);
  }

  /** Dibuja una serie; corta la línea en los huecos y donde `breakIf` lo pide. */
  #series(frames, get, Y, X, color, breakIf = () => false) {
    const x = this.ctx;
    x.strokeStyle = color;
    x.lineWidth = 1.6;
    x.lineJoin = "round";
    x.beginPath();
    let prev = null;
    for (const f of frames) {
      const v = get(f);
      const px = X(f.receivedAt);
      if (!prev || f.receivedAt - prev.t > GAP_MS || breakIf(prev.v, v)) x.moveTo(px, Y(v));
      else x.lineTo(px, Y(v));
      prev = { t: f.receivedAt, v };
    }
    x.stroke();
  }

  #tilt(frames, box, { X, left, right, compact, P }) {
    // Escala simétrica que contiene todo lo visible; solo crece o se achica de a "escalones".
    let peak = 0;
    for (const f of frames) peak = Math.max(peak, Math.abs(f.imu.roll), Math.abs(f.imu.pitch));
    this.tiltScale = TILT_STEPS.find((s) => s >= peak) ?? 180;
    const M = this.tiltScale;
    const pad = 3;
    const Y = (v) => box.y + pad + ((M - v) / (2 * M)) * (box.h - 2 * pad);
    this.#hline(Y(0), left, right, P.rule2);
    this.#hline(Y(M / 2), left, right, P.rule, [2, 3]);
    this.#hline(Y(-M / 2), left, right, P.rule, [2, 3]);
    this.#tick(`+${M}°`, Y(M) + 3, left, P);
    this.#tick("0", Y(0), left, P);
    this.#tick(`−${M}°`, Y(-M) - 3, left, P);
    this.#series(frames, (f) => f.imu.roll, Y, X, P.s1);
    this.#series(frames, (f) => f.imu.pitch, Y, X, P.s2);

    // Leyenda de colores (en la columna de títulos o dentro de la pista).
    const x = this.ctx;
    const lx = compact ? left + 6 : 0;
    const ly = compact ? box.y + 8 : box.y + 26;
    x.font = `600 11px ${P.sans}`;
    x.textAlign = "left";
    x.fillStyle = P.s1;
    x.fillRect(lx, ly - 1, 10, 2.5);
    x.fillText("Roll", lx + 14, ly);
    const lx2 = lx + (compact ? 48 : 0);
    const ly2 = compact ? ly : ly + 16;
    x.fillStyle = P.s2;
    x.fillRect(lx2, ly2 - 1, 10, 2.5);
    x.fillText("Pitch", lx2 + 14, ly2);
  }

  #yaw(frames, box, { X, left, right, compact, P }) {
    const pad = 3;
    const Y = (v) => box.y + pad + ((180 - v) / 360) * (box.h - 2 * pad);
    this.#hline(Y(0), left, right, P.rule2);
    // Con poca altura, solo los extremos: el cero se lee por la línea guía.
    if (box.h >= 34) this.#tick("0", Y(0), left, P);
    this.#tick("+180°", Y(180) + 4, left, P);
    this.#tick("−180°", Y(-180) - 4, left, P);
    const norm = (v) => ((((v + 180) % 360) + 360) % 360) - 180;
    // Al cruzar ±180° el yaw salta: se corta la línea en lugar de trazar una vertical.
    this.#series(frames, (f) => norm(f.imu.yaw), Y, X, P.ink, (a, b) => Math.abs(a - b) > 180);
    if (compact) this.#inlineTitle("Yaw", box, left, P);
  }

  #legs(frames, legs, box, { X, left, right, now, P }) {
    const x = this.ctx;
    if (!legs.length) {
      x.font = `11px ${P.sans}`;
      x.fillStyle = P.muted;
      x.textAlign = "left";
      x.fillText("El robot no informa contacto de patas", left + 8, box.y + box.h / 2);
      return;
    }
    const rh = box.h / legs.length;
    legs.forEach((leg, li) => {
      const ry = box.y + li * rh;
      this.#tick(leg.replace("_foot", ""), ry + rh / 2, left, P, rh < 12 ? 9 : 11);
      x.fillStyle = P.ink2;
      // Rachas de apoyo: un rectángulo por racha (no uno por muestra); un hueco corta la racha.
      let start = null;
      let prev = null;
      const flush = (end) => {
        if (start === null) return;
        const x0 = Math.max(left, X(start));
        x.fillRect(x0, ry + 1.5, Math.max(1, Math.min(right, X(end)) - x0), Math.max(1, rh - 3));
        start = null;
      };
      for (const f of frames) {
        if (prev !== null && f.receivedAt - prev > GAP_MS) flush(prev);
        if (f.fuerzas[leg] === 1) start ??= f.receivedAt;
        else flush(f.receivedAt);
        prev = f.receivedAt;
      }
      flush(now);
    });
  }

  #heat(frames, box, { X, left, right, compact, now, P }) {
    // Color del semáforo de la temperatura máxima de cada muestra (derived.tempMax).
    const x = this.ctx;
    const color = { ok: P.ok, warn: P.warn, crit: P.crit };
    for (let i = 0; i < frames.length; i++) {
      const f = frames[i];
      const t = f.derived.tempMax?.value;
      if (!Number.isFinite(t)) continue;
      const next = frames[i + 1]?.receivedAt ?? now;
      if (next - f.receivedAt > GAP_MS) continue;
      const x0 = Math.max(left, X(f.receivedAt));
      const x1 = Math.min(right, X(next));
      if (x1 <= x0) continue;
      x.fillStyle = color[t > 60 ? "crit" : t >= 40 ? "warn" : "ok"];
      x.fillRect(x0, box.y, x1 - x0 + 0.5, box.h);
    }
    // En el celular no hay columna de títulos: el rótulo va en la de números.
    if (compact) this.#tick("máx", box.y + box.h / 2, left, P);
  }

  /** Alfileres numerados (capturas manuales) y franjas (grabación continua). */
  #captures(captures, { X, t0, top, bottom, now, P }) {
    const x = this.ctx;
    const pins = [];
    let run = null;
    const runs = [];
    // Las capturas están en orden: se recorren desde la más nueva hasta salir de la ventana.
    for (let i = captures.length - 1; i >= 0; i--) {
      const c = captures[i];
      const t = c.frame.receivedAt ?? c.capturedAt.getTime();
      if (t < t0) break;
      if (t > now) continue;
      if (c.tipo === "manual") pins.push({ t, n: c.n });
      else if (run && run.start - t < GAP_MS) run.start = t;
      else runs.push((run = { start: t, end: t }));
    }
    x.fillStyle = P.accent;
    for (const r of runs) {
      x.globalAlpha = 0.14;
      x.fillRect(X(r.start), top, Math.max(2, X(r.end) - X(r.start) + 2), bottom - top);
      x.globalAlpha = 1;
      x.fillRect(X(r.start), top - 2, Math.max(2, X(r.end) - X(r.start) + 2), 2);
    }
    for (const p of pins) {
      const px = Math.round(X(p.t)) + 0.5;
      x.strokeStyle = P.accent;
      x.lineWidth = 1.5;
      x.beginPath();
      x.moveTo(px, top);
      x.lineTo(px, bottom);
      x.stroke();
      const label = String(p.n);
      x.font = `600 11px ${P.mono}`;
      const w = Math.max(16, x.measureText(label).width + 8);
      x.fillStyle = P.accent;
      x.beginPath();
      x.roundRect(px - w / 2, 0, w, 15, 7.5);
      x.fill();
      x.fillStyle = P.onAccent;
      x.textAlign = "center";
      x.textBaseline = "middle";
      x.fillText(label, px, 8);
    }
  }

  #timeAxis({ left, right, plotW, H, P, compact }) {
    const x = this.ctx;
    x.font = `11px ${P.mono}`;
    x.fillStyle = P.muted;
    x.textBaseline = "alphabetic";
    const step = compact ? 10 : 5;
    for (let s = 0; s <= WINDOW_MS / 1000; s += step) {
      const px = right - (s / (WINDOW_MS / 1000)) * plotW;
      x.textAlign = s === 0 ? "right" : px - left < 20 ? "left" : "center";
      x.fillText(s ? `−${s} s` : "ahora", px, H - 3);
    }
  }
}

frontend/js/views/console/BatteryPanel.j.source:
/**
 * Panel de la batería (BMS): carga en un anillo, corriente, temperatura,
 * tensión y potencia, y una barra por celda con la más baja resaltada.
 *
 * La corriente llega en mA y es POSITIVA mientras la batería se descarga.
 * La API de la cátedra puede mandar `celdas: []`: el panel lo dice en vez de
 * dibujar barras vacías.
 */
import { h, s, setText, fmt, clamp } from "../../ui/dom.js";
import { icon } from "../../ui/icons.js";
import { socLevel } from "../../core/telemetryModel.js";
import { setAttr, grouped } from "./util.js";

const RING_R = 44;
const RING_LEN = 2 * Math.PI * RING_R;

/** Rango útil de una celda de litio: 3,3 V vacía, 4,2 V llena. */
const CELL_V = { min: 3.3, max: 4.2 };

/** Diferencia entre la celda más alta y la más baja a partir de la cual se resalta la más baja. */
const CELL_IMBALANCE_MV = 25;

/** Por debajo de este módulo de corriente se considera que la batería está en reposo. */
const IDLE_MA = 50;

export class BatteryPanel {
  constructor() {
    this.sub = h("span", { class: "cv-sub" }, "");
    this.arc = s("circle", { cx: 50, cy: 50, r: RING_R, class: "cv-ring__arc", "stroke-dasharray": RING_LEN.toFixed(1), "stroke-dashoffset": RING_LEN.toFixed(1) });
    this.soc = h("b", { class: "num" }, "—");
    this.ring = h(
      "div",
      { class: "cv-ring", "data-level": "ok" },
      s("svg", { viewBox: "0 0 100 100", "aria-hidden": "true" }, s("circle", { cx: 50, cy: 50, r: RING_R, class: "cv-ring__track" }), this.arc),
      h("div", { class: "cv-ring__c" }, h("div", {}, this.soc, h("span", {}, "% carga"))),
    );
    this.kv = {};
    const row = (key, label, title) => {
      this.kv[key] = h("dd", { class: "num" }, "—");
      return [h("dt", { title }, label), this.kv[key]];
    };
    this.cellTitle = h("span", {}, "Celdas");
    this.cellDelta = h("span", { class: "num" }, "");
    this.cells = h("div", { class: "cv-cells" });
    this.noCells = h("p", { class: "cv-empty", hidden: true }, "El BMS no informa la tensión de cada celda.");
    this.cellEls = [];

    this.el = h(
      "section",
      { class: "cv-panel cv-bms", "aria-labelledby": "cv-bms-title" },
      h("header", { class: "cv-ph" }, h("span", { class: "cv-ph__icon", html: icon("battery", { size: 16 }) }), h("h2", { id: "cv-bms-title" }, "Batería"), this.sub),
      h(
        "div",
        { class: "cv-bms__body" },
        h(
          "div",
          { class: "cv-bms__top" },
          this.ring,
          h(
            "dl",
            { class: "cv-kv" },
            ...row("cur", "Corriente", "Positiva = descargando"),
            ...row("temp", "Temperatura", "Temperatura de la batería"),
            ...row("volt", "Tensión", "Suma de las tensiones de las celdas"),
            ...row("power", "Potencia", "Tensión × corriente"),
          ),
        ),
        h("div", { class: "cv-cellhdr" }, this.cellTitle, this.cellDelta),
        this.cells,
        this.noCells,
      ),
    );
  }

  /** Crea una barra por celda; solo se llama cuando cambia la cantidad de celdas. */
  #buildCells(n) {
    this.cellEls = Array.from({ length: n }, () => {
      const bar = h("i");
      const value = h("span", { class: "num" });
      const el = h("div", { class: "cv-cell", "data-min": "false" }, h("div", { class: "cv-cell__bar", "aria-hidden": "true" }, bar), value);
      return { el, bar, value };
    });
    this.cells.replaceChildren(...this.cellEls.map((c) => c.el));
    this.cells.style.gridTemplateColumns = `repeat(${n}, minmax(0, 1fr))`;
    setText(this.cellTitle, n ? `Celdas · ${n}` : "Celdas");
    this.cells.hidden = n === 0;
    this.noCells.hidden = n > 0;
  }

  update(frame) {
    const { soc, corriente, temperatura, celdas } = frame.bms;
    const d = frame.derived;

    setText(this.soc, fmt(soc, 0));
    setAttr(this.ring, "data-level", socLevel(soc));
    setAttr(this.arc, "stroke-dashoffset", (RING_LEN * (1 - clamp(soc, 0, 100) / 100)).toFixed(1));
    setText(this.sub, Math.abs(corriente) < IDLE_MA ? "sin consumo" : corriente > 0 ? "descargando" : "cargando");

    setText(this.kv.cur, `${grouped(corriente)} mA`);
    setText(this.kv.temp, `${fmt(temperatura, 1)} °C`);
    setText(this.kv.volt, celdas.length ? `${fmt(d.packVoltage, 1)} V` : "—");
    setText(this.kv.power, celdas.length ? `${fmt(d.powerW, 0)} W` : "—");

    if (celdas.length !== this.cellEls.length) this.#buildCells(celdas.length);
    const imbalanced = d.cellDeltaMv !== null && d.cellDeltaMv > CELL_IMBALANCE_MV;
    celdas.forEach((v, i) => {
      const c = this.cellEls[i];
      setAttr(c.el, "data-min", imbalanced && v === d.cellMin);
      setText(c.value, fmt(v, 2));
      c.bar.style.transform = `scaleY(${clamp((v - CELL_V.min) / (CELL_V.max - CELL_V.min), 0.04, 1).toFixed(3)})`;
    });
    setText(this.cellDelta, celdas.length ? `mín. ${fmt(d.cellMin, 2)} V · Δ ${d.cellDeltaMv} mV` : "");
  }
}

