/**
 * Panel de contacto de las patas (`fuerzas`: 1 = apoyada, 0 = en el aire).
 *
 * A la izquierda, el robot dibujado: el Go2 visto desde arriba y el G1 de
 * frente. El pie que apoya se rellena y crece un poco. A la derecha, una
 * fila por pata con su "diagrama de apoyos" de los últimos 4 s (40 muestras):
 * cada cuadradito es una muestra, lleno si la pata estaba apoyada. Así se ve
 * la marcha: en el trote del Go2 las patas en diagonal apoyan juntas.
 *
 * El dibujo se puede cambiar por el modelo 3D real de Unitree (botón
 * "Esquema | 3D", tecla G): FigureSwitch monta el 3D encima del esquema y lo
 * oculta, así el panel no cambia de tamaño. Las filas de apoyos quedan igual.
 */
import { h, s, setText } from "../../ui/dom.js";
import { icon } from "../../ui/icons.js";
import { LEG_LABELS } from "../../core/telemetryModel.js";
import { FigureSwitch, figureToggle } from "../../ui/FigureSwitch.js";
import { setAttr } from "./util.js";

/** Muestras del diagrama de apoyos (4 s a 10 Hz). */
const STRIP = 40;

/** Orden "espacial" de las filas: como se ven en el dibujo. */
const SPATIAL = ["FL", "FR", "RL", "RR", "R_foot", "L_foot"];

/** Ordena las patas como aparecen en el dibujo (izquierda a derecha, adelante hacia atrás). */
export const spatialOrder = (patas) => [...patas].sort((a, b) => SPATIAL.indexOf(a) - SPATIAL.indexOf(b));

/** Etiqueta corta de cada pata para la lista. */
const SHORT = { R_foot: "Der.", L_foot: "Izq." };

/** Go2 visto desde arriba (la cabeza arriba). Devuelve el SVG y sus pies por nombre. */
function drawQuadruped() {
  const feet = {};
  const foot = (id, cx, cy) => (feet[id] = s("circle", { class: "cv-foot", cx, cy, r: 9, "data-down": "false" }));
  const svg = s(
    "svg",
    { class: "cv-robot", viewBox: "0 0 132 168", role: "img", "aria-label": "Go2 visto desde arriba, con la cabeza hacia arriba" },
    s("path", { class: "cv-robot__leg", d: "M46 46 34 44 22 26M86 46l12-2 12-18M46 122l-12 2-12 18M86 122l12 2 12 18" }),
    s("g", { class: "cv-robot__joint" }, ...[[34, 44], [98, 44], [34, 124], [98, 124]].map(([cx, cy]) => s("circle", { cx, cy, r: 3.5 }))),
    s("rect", { class: "cv-robot__body", x: 40, y: 30, width: 52, height: 108, rx: 16 }),
    s("rect", { class: "cv-robot__inner", x: 47, y: 40, width: 38, height: 88, rx: 10 }),
    s("path", { class: "cv-robot__body", d: "M50 30c0-10 7-16 16-16s16 6 16 16" }),
    s("circle", { class: "cv-robot__eye", cx: 60, cy: 22, r: 2.2 }),
    s("circle", { class: "cv-robot__eye", cx: 72, cy: 22, r: 2.2 }),
    s("g", { class: "cv-robot__hip" }, ...[[46, 46], [86, 46], [46, 122], [86, 122]].map(([cx, cy]) => s("circle", { cx, cy, r: 4 }))),
    s("path", { class: "cv-robot__inner", d: "M58 76h16M58 84h16M58 92h16" }),
    foot("FL", 22, 26), foot("FR", 110, 26), foot("RL", 22, 142), foot("RR", 110, 142),
    s(
      "g",
      { class: "cv-robot__lbl" },
      ...[["FL", 14, 66], ["FR", 118, 66], ["RL", 14, 108], ["RR", 118, 108]].map(([t, x, y]) => s("text", { x, y, "text-anchor": "middle" }, document.createTextNode(t))),
    ),
    s("text", { class: "cv-robot__caption", x: 66, y: 164, "text-anchor": "middle" }, document.createTextNode("▲ frente")),
  );
  return { svg, feet };
}

/** G1 visto de frente: su pie derecho queda a la izquierda de quien mira. */
function drawBiped() {
  const feet = {};
  const foot = (id, x) => (feet[id] = s("rect", { class: "cv-foot", x, y: 140, width: 28, height: 13, rx: 6.5, "data-down": "false" }));
  const svg = s(
    "svg",
    { class: "cv-robot", viewBox: "0 0 132 168", role: "img", "aria-label": "G1 visto de frente: su pie derecho está a la izquierda del dibujo" },
    s("path", { class: "cv-robot__leg", d: "M47 42 36 64 32 88M85 42l11 22 4 24M57 92l-3 24 -4 22M75 92l3 24 4 22" }),
    s("g", { class: "cv-robot__joint" }, ...[[36, 64], [96, 64], [54, 116], [78, 116]].map(([cx, cy]) => s("circle", { cx, cy, r: 3.5 }))),
    s("rect", { class: "cv-robot__body", x: 45, y: 34, width: 42, height: 50, rx: 12 }),
    s("rect", { class: "cv-robot__body", x: 50, y: 82, width: 32, height: 14, rx: 6 }),
    s("path", { class: "cv-robot__inner", d: "M58 52h16M58 60h16M58 68h16" }),
    s("circle", { class: "cv-robot__body", cx: 66, cy: 20, r: 11 }),
    s("rect", { class: "cv-robot__eye", x: 59, y: 17, width: 14, height: 4, rx: 2 }),
    foot("R_foot", 34), foot("L_foot", 70),
    s(
      "g",
      { class: "cv-robot__lbl" },
      s("text", { x: 22, y: 151, "text-anchor": "middle" }, document.createTextNode("R")),
      s("text", { x: 110, y: 151, "text-anchor": "middle" }, document.createTextNode("L")),
    ),
    s("text", { class: "cv-robot__caption", x: 66, y: 166, "text-anchor": "middle" }, document.createTextNode("vista de frente")),
  );
  return { svg, feet };
}

export class FeetPanel {
  /** @param {object} ctx contexto de la vista (FigureSwitch lo necesita para el estado y las acciones) */
  constructor(ctx) {
    this.ctx = ctx;
    this.sub = h("span", { class: "cv-sub" }, "");
    this.toggle = figureToggle(ctx, { compact: true });
    // El área del dibujo es fija: adentro se cambia el SVG (Go2 ↔ G1) y encima va la capa 3D.
    this.schematic = h("div", { class: "cv-figure__svg" });
    this.figure = h("div", { class: "cv-figure" }, this.schematic);
    this.legsEl = h("div", { class: "cv-legs" });
    this.legs = [];
    this.fig = null;
    this.mode = ctx.state.figure ?? "esquema";
    this.el = h(
      "section",
      { class: "cv-panel cv-feet", "aria-labelledby": "cv-feet-title" },
      h(
        "header",
        { class: "cv-ph" },
        h("span", { class: "cv-ph__icon", html: icon("feet", { size: 16 }) }),
        h("h2", { id: "cv-feet-title" }, "Patas"),
        this.sub,
        this.toggle,
      ),
      h("div", { class: "cv-feet__body" }, this.figure, this.legsEl),
    );
  }

  /** Dibuja el robot y una fila por pata según `info.patas` (Go2: 4, G1: 2). */
  build(info) {
    const patas = spatialOrder(info.patas ?? []);
    const biped = patas.length !== 4 && info.tipo !== "cuadrupedo";
    const drawing = biped ? drawBiped() : drawQuadruped();
    this.schematic.replaceChildren(drawing.svg);
    this.#ensureFigure(biped ? "frente" : "arriba", info);

    if (!patas.length) {
      this.legs = [];
      this.legsEl.replaceChildren(h("p", { class: "cv-empty" }, "Este robot no informa el contacto de las patas."));
      return;
    }
    this.legs = patas.map((pata) => {
      const cells = Array.from({ length: STRIP }, () => h("i", { "data-on": "false" }));
      const state = h("span", { class: "cv-legrow__st", "data-down": "false" }, "");
      const row = h(
        "div",
        { class: "cv-legrow", title: LEG_LABELS[pata] ?? pata },
        h("b", {}, SHORT[pata] ?? pata),
        h("div", { class: "cv-steps", "aria-hidden": "true" }, ...cells),
        state,
      );
      return { pata, row, cells, state, foot: drawing.feet[pata] };
    });
    this.legsEl.replaceChildren(...this.legs.map((l) => l.row));
  }

  /**
   * El encuadre de la cámara 3D es fijo por escena: el Go2 se ve desde arriba
   * (como el esquema) y el G1 de frente. Si cambia el robot, se rehace la escena.
   */
  #ensureFigure(preset, info) {
    if (this.fig?.opts.preset !== preset) {
      this.fig?.destroy();
      this.fig = new FigureSwitch(this.ctx, { host: this.figure, schematic: this.schematic, preset, interactive: false, labels: false });
      this.fig.setMode(this.mode);
    }
    this.fig.setInfo(info);
  }

  /** "esquema" o "3d" (preferencia global; la llama la vista en onFigureMode). */
  setFigureMode(mode) {
    this.mode = mode;
    this.toggle.set(mode);
    this.fig?.setMode(mode);
  }

  setPaused(paused) {
    this.fig?.setPaused(paused);
  }

  applyTheme() {
    this.fig?.applyTheme();
  }

  destroy() {
    this.fig?.destroy();
    this.fig = null;
  }

  update(frame, history) {
    this.fig?.update(frame);
    if (!this.legs.length) return;
    const samples = history.tail(STRIP);
    const offset = STRIP - samples.length; // al principio hay menos de 40 muestras: se alinean a la derecha
    for (const leg of this.legs) {
      const down = frame.fuerzas[leg.pata] === 1;
      setAttr(leg.state, "data-down", down);
      setText(leg.state, down ? "apoyada" : "en el aire");
      if (leg.foot) setAttr(leg.foot, "data-down", down);
      for (let i = 0; i < STRIP; i++) {
        const f = samples[i - offset];
        setAttr(leg.cells[i], "data-on", f ? f.fuerzas[leg.pata] === 1 : false);
      }
    }
    const span = samples.length > 1 ? samples.at(-1).ts - samples[0].ts : 0;
    setText(this.sub, `${frame.derived.contacts} de ${frame.derived.legs} apoyadas · últimos ${Math.round(span)} s`);
  }
}

frontend/js/views/console/ImuPanel.js.source:
/**
 * Panel de la IMU: horizonte artificial, valores de roll / pitch / yaw y un
 * gráfico histórico con Chart.js (≥ 60 muestras, por consigna).
 *
 * Roll y pitch del robot caminando son de 1 a 3°: en un horizonte a escala
 * real casi no se moverían. Por eso el horizonte los exagera ×4, y lo dice.
 */
import { h, s, setText, fmt } from "../../ui/dom.js";
import { icon } from "../../ui/icons.js";
import { DEFAULTS } from "../../config.js";
import { createConsoleChart, destroyConsoleChart, toPoints } from "./consoleChart.js";

/** Exageración del horizonte (está rotulada en el dibujo). */
const HORIZON_GAIN = 4;

/** Muestras del gráfico: 150 (≈ 15 s a 10 Hz), más que las 60 que pide la consigna. */
const WINDOW = Math.max(60, DEFAULTS.chartWindow);

const SERIES = [
  { key: "roll", label: "Roll", token: "--cv-s1", on: true },
  { key: "pitch", label: "Pitch", token: "--cv-s2", on: true },
  { key: "yaw", label: "Yaw", token: "--cv-s3", on: false },
];

export class ImuPanel {
  constructor({ root }) {
    this.root = root;
    this.points = { roll: [], pitch: [], yaw: [] };
    this.sub = h("span", { class: "cv-sub" }, `${WINDOW} muestras`);
    this.chips = SERIES.map((sr) =>
      h(
        "button",
        { type: "button", class: "cv-chip", "aria-pressed": String(sr.on), style: { "--c": `var(${sr.token})` }, onclick: (e) => this.#toggleSeries(sr.key, e.currentTarget) },
        h("i", { class: "cv-sw", "aria-hidden": "true" }),
        sr.label,
      ),
    );

    this.horizon = this.#buildHorizon();
    this.value = {};
    const stat = (key, label, extra = null) => {
      this.value[key] = h("span", {}, "—");
      return h(
        "div",
        { class: "cv-stat" },
        h("div", { class: "cv-stat__lbl" }, extra ?? h("i", { class: "cv-sw", style: { background: `var(--cv-s${key === "roll" ? 1 : 2})` }, "aria-hidden": "true" }), label),
        h("div", { class: "cv-stat__val num" }, this.value[key], h("small", {}, "°")),
      );
    };
    this.needle = s("g", {}, s("path", { d: "M0-9 3 0H-3Z", class: "cv-needle-n" }), s("path", { d: "M0 9 3 0H-3Z", class: "cv-needle-s" }));
    const compass = s("svg", { class: "cv-compass", viewBox: "-13 -13 26 26", "aria-hidden": "true" }, s("circle", { r: 11, class: "cv-compass__ring" }), this.needle);

    this.canvas = h("canvas", { role: "img", "aria-label": "Gráfico histórico de roll, pitch y yaw en grados" });
    this.el = h(
      "section",
      { class: "cv-panel cv-imu", "aria-labelledby": "cv-imu-title" },
      h(
        "header",
        { class: "cv-ph" },
        h("span", { class: "cv-ph__icon", html: icon("compass", { size: 16 }) }),
        h("h2", { id: "cv-imu-title" }, "Inclinación (IMU)"),
        this.sub,
        h("div", { class: "cv-chips", role: "group", "aria-label": "Series del gráfico" }, ...this.chips),
      ),
      h(
        "div",
        { class: "cv-imu__body" },
        this.horizon.el,
        h(
          "div",
          { class: "cv-imu__right" },
          h("div", { class: "cv-stats" }, stat("roll", "Roll"), stat("pitch", "Pitch"), stat("yaw", "Yaw", compass)),
          h("div", { class: "cv-chartbox" }, this.canvas),
        ),
      ),
    );
  }

  #buildHorizon() {
    const world = s(
      "g",
      { class: "cv-hz__world" },
      s("rect", { x: -200, y: -200, width: 400, height: 200, class: "cv-hz__sky" }),
      s("rect", { x: -200, y: 0, width: 400, height: 200, class: "cv-hz__ground" }),
      s("line", { x1: -200, x2: 200, y1: 0, y2: 0, class: "cv-hz__line" }),
      // Escalera de cabeceo: cada raya son 5° reales (20 unidades = 5° × 4).
      s("g", { class: "cv-hz__ladder" }, ...[-40, -20, 20, 40].map((y) => s("line", { x1: Math.abs(y) === 40 ? -14 : -8, x2: Math.abs(y) === 40 ? 14 : 8, y1: y, y2: y }))),
    );
    const svg = s(
      "svg",
      { viewBox: "-80 -80 160 160", role: "img", "aria-label": "Horizonte artificial: roll y pitch exagerados cuatro veces" },
      world,
      s("path", { d: "M-44 0h28l6 8 6-8h28", class: "cv-hz__plane" }),
      s("circle", { r: 2.5, class: "cv-hz__dot" }),
      s("text", { x: 0, y: -62, "text-anchor": "middle", class: "cv-hz__gain" }, document.createTextNode(`×${HORIZON_GAIN}`)),
    );
    return { el: h("div", { class: "cv-horizon" }, svg), world };
  }

  init() {
    this.chart = createConsoleChart(this.canvas, this.root, { yTitle: "°", y2: true, y2Title: "yaw °", yMin: -5, yMax: 5 });
    this.chart.options.scales.y2.ticks.stepSize = 90;
    this.chart.data.datasets = SERIES.map((sr) => ({
      label: sr.label,
      data: this.points[sr.key],
      $color: sr.token,
      yAxisID: sr.key === "yaw" ? "y2" : "y",
      borderDash: sr.key === "yaw" ? [5, 3] : undefined,
      borderWidth: sr.key === "yaw" ? 1.5 : 2,
      hidden: !sr.on,
    }));
    this.chart.options.scales.y2.display = SERIES[2].on;
    this.chart.options.plugins.tooltip.callbacks.label = (item) => ` ${item.dataset.label}: ${fmt(item.parsed.y, 1, { sign: true })}°`;
    this.chart.$recolor();
    this.chart.update("none");
  }

  #toggleSeries(key, btn) {
    const i = SERIES.findIndex((sr) => sr.key === key);
    const ds = this.chart.data.datasets[i];
    ds.hidden = !ds.hidden;
    btn.setAttribute("aria-pressed", String(!ds.hidden));
    if (key === "yaw") this.chart.options.scales.y2.display = !ds.hidden;
    this.chart.update("none");
  }

  update(frame, history) {
    const { roll, pitch, yaw } = frame.imu;
    setText(this.value.roll, fmt(roll, 1, { sign: true }));
    setText(this.value.pitch, fmt(pitch, 1, { sign: true }));
    setText(this.value.yaw, fmt(yaw, 0));
    // Yaw positivo = giro antihorario visto desde arriba; la aguja apunta hacia donde mira el robot.
    this.needle.setAttribute("transform", `rotate(${(-yaw).toFixed(1)})`);
    // Convención de la IMU (x adelante, y izquierda, z arriba): roll > 0 baja el lado derecho y
    // pitch > 0 baja la nariz. Como en un avión, el que se mueve es el horizonte, en sentido contrario.
    this.horizon.world.setAttribute("transform", `rotate(${(-roll * HORIZON_GAIN).toFixed(2)}) translate(0 ${(-pitch * HORIZON_GAIN).toFixed(2)})`);

    if (!this.chart) return;
    const samples = history.tail(WINDOW);
    toPoints(samples, (f) => f.imu.roll, this.points.roll);
    toPoints(samples, (f) => f.imu.pitch, this.points.pitch);
    toPoints(samples, (f) => f.imu.yaw, this.points.yaw, { wrap: true });
    const span = samples.length > 1 ? samples.at(-1).ts - samples[0].ts : 0;
    this.chart.options.scales.x.min = Math.min(-span, -1);
    setText(this.sub, `${samples.length} ${samples.length === 1 ? "muestra" : "muestras"} · ${fmt(span, 0)} s`);
    this.chart.update("none");
  }

  destroy() {
    destroyConsoleChart(this.chart);
    this.chart = null;
  }
}

