/**
 * Sonido de la cabina (Web Audio, sin archivos): una pisada por pata al
 * apoyar, una alarma doble sobre 60 °C y un clic al capturar.
 *
 * Arranca APAGADO. El `AudioContext` se crea recién cuando el usuario lo
 * prende (tecla S o botón): los navegadores no dejan sonar audio sin un
 * gesto del usuario, y así tampoco se reserva el dispositivo de audio si
 * nadie lo usa. `destroy()` lo cierra al salir de la vista.
 */

/** Un tono distinto por pata: con el sonido prendido, el trote "se escucha". */
const FOOT_HZ = { FR: 220, FL: 247, RR: 196, RL: 175, R_foot: 220, L_foot: 196 };
/** Separación mínima entre alarmas, para avisar sin aturdir. */
const ALARM_EVERY_MS = 2500;

export class CockpitSound {
  #ctx = null;
  #lastAlarm = -Infinity;
  enabled = false;

  /** Prende o apaga. Debe llamarse desde un gesto del usuario (tecla o clic). */
  toggle(force) {
    this.enabled = force ?? !this.enabled;
    if (this.enabled) {
      const Ctx = window.AudioContext ?? window.webkitAudioContext;
      if (!Ctx) {
        this.enabled = false;
        return false;
      }
      this.#ctx ??= new Ctx();
      if (this.#ctx.state === "suspended") this.#ctx.resume();
    }
    return this.enabled;
  }

  /** "Tic" de una pata que acaba de apoyar. */
  step(leg) {
    this.#tone(FOOT_HZ[leg] ?? 200, 0.06, 0.05, "triangle");
  }

  /** Alarma doble (agudo-grave), como mucho cada 2,5 s mientras dure la condición. */
  alarm() {
    const now = performance.now();
    if (!this.enabled || now - this.#lastAlarm < ALARM_EVERY_MS) return;
    this.#lastAlarm = now;
    this.#tone(880, 0.12, 0.06, "sine");
    this.#tone(660, 0.16, 0.06, "sine", 0.15);
  }

  /** Clic de obturador al capturar. */
  shutter() {
    this.#tone(1320, 0.05, 0.04, "square");
  }

  /** Un tono corto con envolvente (ataque de 5 ms, caída exponencial) para que no "chasquee". */
  #tone(freq, dur, vol, type, delay = 0) {
    const ctx = this.#ctx;
    if (!this.enabled || !ctx || ctx.state !== "running") return;
    const t = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(vol, t + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(gain).connect(ctx.destination);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  destroy() {
    this.enabled = false;
    this.#ctx?.close();
    this.#ctx = null;
  }
}

frontend/js/views/pilot/MotorRing.js.source:
/**
 * Anillo de motores alrededor de la silueta del robot (SVG).
 *
 * Cada motor es un segmento ubicado en el cuadrante de su pata (Go2) o de su
 * miembro (G1), pintado con el semáforo de temperatura. Un arco interior,
 * más grueso cuanto más torque, muestra el esfuerzo. Las patas (o pies) se
 * encienden al apoyar.
 *
 * Todo el SVG se crea en `build(info)`; `update(frame)` solo cambia
 * atributos y textos, y solo cuando el valor cambió.
 */
import { s, setText, fmt } from "../../ui/dom.js";
import { tempLevel, LEG_LABELS } from "../../core/telemetryModel.js";
import { RING_R as R, layoutRing, layoutFeet, polar, arcPath } from "./ringLayout.js";

/** Torque mínimo (N·m) que llena el arco: el mismo piso que el campo del umbral en la consola. */
const MIN_TORQUE_SCALE = 1;

/** Cuántas etiquetas de motor caliente se muestran a la vez (más, se pisan). */
const MAX_CALLOUTS = 3;
/** Distancia al centro de la silueta donde terminan las patas dibujadas. */
const LEG_REACH = R - 44;
/** En el humanoide los pies van adentro del anillo, al final de las piernas, con el rótulo debajo. */
const FOOT_INSIDE_R = 112;
/** Altura máxima (fracción de R) de las etiquetas de motor, para que no salgan del anillo hacia arriba o abajo. */
const CALLOUT_MAX_Y = 0.72;
/** Separación angular mínima (°) entre dos etiquetas de motor para que no se encimen. */
const CALLOUT_MIN_GAP = 28;

export class MotorRing {
  /**
   * @param {{ onSelect: (name: string) => void }} opts
   */
  constructor({ onSelect }) {
    this.onSelect = onSelect;
    this.byName = new Map();
    this.feet = new Map();
    this.selected = null;
    // Contenedor fijo de la silueta: se rellena en cada build() pero el nodo es siempre
    // el mismo, para que quien lo oculte (el modo "3D real") no pierda la referencia.
    this.figure = s("g", { class: "pv-ring__figure" });
    this.svg = s("svg", {
      class: "pv-ring__svg",
      viewBox: "-250 -250 500 500",
      role: "img",
      "aria-label": "Anillo de motores: cada segmento es un motor con el color de su temperatura",
    });
  }

  /** Reconstruye el anillo para el robot conectado (Go2 ↔ G1). */
  build(info) {
    const names = info?.motores_nombres ?? [];
    const legs = info?.patas ?? [];
    const { kind, segments, groups } = layoutRing(names);
    this.kind = kind;
    this.byName.clear();
    this.feet.clear();

    const guides = s(
      "g",
      { class: "pv-ring__guides", "aria-hidden": "true" },
      s("circle", { r: R + 14, class: "pv-ring__outer" }),
      s("circle", { r: R - 30, class: "pv-ring__inner" }),
    );

    const silhouette = this.#silhouette(kind, legs);
    this.stateText = s("text", { class: "pv-ring__state", x: 0, y: kind === "humanoide" ? -6 : 4, "text-anchor": "middle" }, "—");
    silhouette.append(this.stateText);

    const segLayer = s("g", { class: "pv-ring__segments" });
    const calloutLayer = s("g", { class: "pv-ring__callouts", "aria-hidden": "true" });
    for (const seg of segments) {
      const d = arcPath(R, seg.a0, seg.a1);
      const main = s("path", { class: "pv-seg__main", d });
      const g = s(
        "g",
        { class: "pv-seg", "data-level": "unknown", "data-name": seg.name },
        s("title", {}, seg.name),
        s("path", { class: "pv-seg__glow", d }),
        main,
        s("path", { class: "pv-seg__torque", d: arcPath(R - 18, seg.a0, seg.a1) }),
        s("path", { class: "pv-seg__pick", d: arcPath(R + 22, seg.a0, seg.a1) }),
      );
      g.addEventListener("click", () => this.onSelect(seg.name));
      segLayer.append(g);

      const callout = this.#callout(seg);
      calloutLayer.append(callout.g);
      this.byName.set(seg.name, {
        g,
        torque: g.querySelector(".pv-seg__torque"),
        callout,
        level: "unknown",
        torqueW: "",
        over: false,
        temp: NaN,
        mid: seg.mid,
      });
    }

    // En el humanoide los grupos no son patas: se rotulan por dentro del anillo.
    const groupLabels = s("g", { class: "pv-ring__groups", "aria-hidden": "true" });
    if (kind === "humanoide") {
      for (const g of groups) {
        const [x, y] = polar(R - 46, g.mid);
        groupLabels.append(s("text", { x: x.toFixed(1), y: (y + 4).toFixed(1), "text-anchor": "middle" }, g.short));
      }
    }

    const feetLayer = s("g", { class: "pv-ring__feet" });
    for (const foot of layoutFeet(legs)) {
      // Go2: las patas van afuera del anillo, en las diagonales. G1: los pies van al
      // final de las piernas de la silueta, adentro, con el rótulo debajo.
      const inside = kind === "humanoide";
      const [cx, cy] = polar(inside ? FOOT_INSIDE_R : R + 40, foot.angle);
      const [lx, ly] = inside ? [cx, cy + 26] : polar(R + 66, foot.angle);
      const g = s(
        "g",
        { class: "pv-foot", "data-contact": "0" },
        s("title", {}, LEG_LABELS[foot.leg] ?? foot.leg),
        s("circle", { class: "pv-foot__ring", cx: cx.toFixed(1), cy: cy.toFixed(1), r: 11 }),
        // El relleno es un círculo aparte: "encenderlo" es animar solo su opacidad.
        s("circle", { class: "pv-foot__dot", cx: cx.toFixed(1), cy: cy.toFixed(1), r: 11 }),
        s("text", { x: lx.toFixed(1), y: (ly + 5).toFixed(1), "text-anchor": "middle" }, foot.label),
      );
      feetLayer.append(g);
      this.feet.set(foot.leg, { g, line: silhouette.querySelector(`[data-leg="${foot.leg}"]`), contact: -1 });
    }
    if (!legs.length) {
      feetLayer.append(s("text", { class: "pv-ring__nofeet", x: 0, y: R + 56, "text-anchor": "middle" }, `${(info?.modelo ?? "").toUpperCase()} · SIN DATOS DE PATAS`));
    }

    this.figure.replaceChildren(silhouette);
    this.svg.replaceChildren(guides, this.figure, groupLabels, segLayer, feetLayer, calloutLayer);
    this.setSelected(this.byName.has(this.selected) ? this.selected : null);
  }

  /** Silueta del robot: Go2 visto desde arriba, G1 visto desde atrás. */
  #silhouette(kind, legs) {
    const g = s("g", { class: "pv-silhouette", "aria-hidden": "true" });
    const feet = new Map(layoutFeet(legs).map((f) => [f.leg, f.angle]));
    const leg = (name, x0, y0, fallback) => {
      const reach = kind === "humanoide" ? FOOT_INSIDE_R : LEG_REACH;
      const [x1, y1] = feet.has(name) ? polar(reach, feet.get(name)) : fallback;
      return s("line", { class: "pv-silhouette__leg", "data-leg": name, x1: x0, y1: y0, x2: x1.toFixed(1), y2: y1.toFixed(1) });
    };

    if (kind === "cuadrupedo") {
      const d = LEG_REACH * Math.SQRT1_2;
      g.append(
        leg("FL", -26, -54, [-d, -d]),
        leg("FR", 26, -54, [d, -d]),
        leg("RL", -26, 54, [-d, d]),
        leg("RR", 26, 54, [d, d]),
        s("rect", { class: "pv-silhouette__body", x: -30, y: -66, width: 60, height: 132, rx: 18 }),
        s("rect", { class: "pv-silhouette__body", x: -18, y: -86, width: 36, height: 22, rx: 9 }),
      );
    } else {
      g.append(
        s("line", { class: "pv-silhouette__limb", x1: -34, y1: -40, x2: -58, y2: 22 }),
        s("line", { class: "pv-silhouette__limb", x1: 34, y1: -40, x2: 58, y2: 22 }),
        leg("L_foot", -14, 32, [-18, 100]),
        leg("R_foot", 14, 32, [18, 100]),
        s("circle", { class: "pv-silhouette__body", cx: 0, cy: -70, r: 16 }),
        s("rect", { class: "pv-silhouette__body", x: -30, y: -50, width: 60, height: 84, rx: 16 }),
      );
    }
    return g;
  }

  /** Etiqueta de motor caliente: línea guía desde el segmento + temperatura + nombre. */
  #callout(seg) {
    const [x1, y1] = polar(R + 26, seg.mid);
    const right = Math.cos((seg.mid * Math.PI) / 180) >= 0;
    // Los motores de arriba y de abajo (torso, rodillas del G1) se rotulan hacia el
    // costado: si no, el texto pisaría la cinta de rumbo o la línea de estado.
    let [x2, y2] = polar(R + 62, seg.mid);
    const yMax = R * CALLOUT_MAX_Y;
    if (Math.abs(y2) > yMax) {
      y2 = Math.sign(y2) * yMax;
      x2 = (right ? 1 : -1) * Math.sqrt((R + 44) ** 2 - y2 * y2);
    }
    const x3 = x2 + (right ? 22 : -22);
    const tx = x3 + (right ? 6 : -6);
    const anchor = right ? "start" : "end";
    const temp = s("text", { class: "pv-callout__temp", x: tx.toFixed(1), y: (y2 + 3).toFixed(1), "text-anchor": anchor }, "");
    const g = s(
      "g",
      { class: "pv-callout", visibility: "hidden", "data-level": "unknown" },
      s("polyline", { points: `${x1.toFixed(1)},${y1.toFixed(1)} ${x2.toFixed(1)},${y2.toFixed(1)} ${x3.toFixed(1)},${y2.toFixed(1)}` }),
      temp,
      s("text", { class: "pv-callout__name", x: tx.toFixed(1), y: (y2 + 22).toFixed(1), "text-anchor": anchor }, seg.name),
    );
    return { g, temp, on: false, level: "unknown" };
  }

  /** Marca un motor (desde el anillo o la tabla). `null` desmarca. */
  setSelected(name) {
    this.selected = name;
    for (const [n, e] of this.byName) {
      const on = n === name;
      e.g.toggleAttribute("data-selected", on);
      e.callout.g.toggleAttribute("data-selected", on);
    }
  }

  /**
   * @param {object} frame  muestra normalizada
   * @param {{ torqueRef: number }} opts  torque (N·m) que llena el arco: el umbral de alarma
   */
  update(frame, { torqueRef }) {
    // Escala del arco: con un umbral 0 (p. ej. guardado a mano), 0/0 daba stroke-width="NaN" (spec 010 · FR-008).
    const scale = Math.max(MIN_TORQUE_SCALE, torqueRef);
    for (const m of frame.motores) {
      const e = this.byName.get(m.nombre);
      if (!e) continue;
      e.temp = m.temperatura;
      const level = tempLevel(m.temperatura);
      if (level !== e.level) {
        e.g.setAttribute("data-level", level);
        e.level = level;
      }
      const tau = Math.abs(m.torque);
      const width = (2 + Math.min(1, tau / scale) * 8).toFixed(1);
      if (width !== e.torqueW) {
        e.torque.setAttribute("stroke-width", width);
        e.torqueW = width;
      }
      const over = tau > torqueRef;
      if (over !== e.over) {
        e.g.toggleAttribute("data-torque-alarm", over);
        e.over = over;
      }
    }
    this.#updateCallouts(frame);

    for (const [leg, foot] of this.feet) {
      const contact = frame.fuerzas[leg] === 1 ? 1 : 0;
      if (contact === foot.contact) continue;
      foot.contact = contact;
      foot.g.setAttribute("data-contact", String(contact));
      foot.line?.setAttribute("data-contact", String(contact));
    }
    setText(this.stateText, frame.derived.isMoving ? "CAMINA" : "QUIETO");
  }

  /** Rotula los motores sobre 60 °C (los más calientes primero), el elegido, o si no el más caliente. */
  #updateCallouts(frame) {
    // Los más calientes primero; si dos motores vecinos están calientes, se rotula solo
    // el peor (sus etiquetas caerían una encima de la otra).
    const hot = [];
    const ranked = [...this.byName.entries()].filter(([, e]) => e.level === "crit").sort((a, b) => b[1].temp - a[1].temp);
    for (const [name, e] of ranked) {
      if (hot.length === MAX_CALLOUTS) break;
      if (hot.every((n) => Math.abs(this.byName.get(n).mid - e.mid) >= CALLOUT_MIN_GAP)) hot.push(name);
    }
    const shown = new Set(hot.length ? hot : [frame.derived.tempMax?.motor]);
    if (this.selected) shown.add(this.selected);

    for (const [name, e] of this.byName) {
      const c = e.callout;
      const on = shown.has(name);
      if (on !== c.on) {
        c.g.setAttribute("visibility", on ? "visible" : "hidden");
        c.on = on;
      }
      if (!on) continue;
      setText(c.temp, `${fmt(e.temp, 1)}°`);
      if (c.level !== e.level) {
        c.g.setAttribute("data-level", e.level);
        c.level = e.level;
      }
    }
  }
}

frontend/js/views/pilot/MotorSheet.js.source:
/**
 * Hoja lateral con la tabla de motores y la batería completa (tecla M).
 *
 * En la cabina la tabla no está a la vista: vive acá para que la pantalla
 * principal sea solo forma. Es un `<dialog>` nativo: atrapa el foco, se
 * cierra con Esc sin código extra y lo anuncia bien un lector de pantalla.
 * Se cierra también con un clic afuera (en el fondo).
 *
 * Las filas se crean en `build(info)`; `update()` solo escribe textos y solo
 * mientras la hoja está abierta.
 */
import { h, setText, fmt } from "../../ui/dom.js";
import { tempLevel, motorGroup, socLevel } from "../../core/telemetryModel.js";
import { icon } from "../../ui/icons.js";
import { milliamps, currentSense } from "./format.js";

/** Qué pata (o pie) corresponde a cada grupo de la tabla, para mostrar si apoya. */
const GROUP_LEG = { FR: "FR", FL: "FL", RR: "RR", RL: "RL", L_pierna: "L_foot", R_pierna: "R_foot" };

export class MotorSheet {
  /**
   * @param {{ onSelect: (name: string) => void, onToggle: (open: boolean) => void }} opts
   */
  constructor({ onSelect, onToggle }) {
    this.onSelect = onSelect;
    this.rows = new Map();
    this.groupLegs = [];
    this.cellChips = [];

    this.tbody = h("tbody");
    this.bat = {
      soc: h("dd", {}, "—"),
      current: h("dd", {}, "—"),
      temp: h("dd", {}, "—"),
      pack: h("dd", {}, "—"),
      power: h("dd", {}, "—"),
    };
    this.cells = h("ol", { class: "pv-sheet__cells", "aria-label": "Tensión de cada celda" });

    const close = h("button", { type: "button", class: "pv-btn pv-btn--icon", "aria-label": "Cerrar la tabla", html: icon("x"), onclick: () => this.toggle(false) });
    this.dialog = h(
      "dialog",
      { class: "pv-sheet", "aria-labelledby": "pv-sheet-title" },
      h(
        "div",
        { class: "pv-sheet__inner" },
        h("header", { class: "pv-sheet__head" }, h("h2", { id: "pv-sheet-title" }, "Motores"), close),
        h(
          "p",
          { class: "pv-sheet__legend" },
          h("i", { "data-level": "ok" }), "< 40 °C ", h("i", { "data-level": "warn" }), "40–60 °C ", h("i", { "data-level": "crit" }), "> 60 °C",
          h("span", {}, " · Tocá un motor para marcarlo en el anillo."),
        ),
        h(
          "div",
          { class: "pv-sheet__table" },
          h(
            "table",
            {},
            h("caption", { class: "sr-only" }, "Temperatura, ángulo, velocidad y torque de cada motor"),
            h(
              "thead",
              {},
              h("tr", {}, h("th", { scope: "col" }, "Motor"), h("th", { scope: "col" }, "Temp °C"), h("th", { scope: "col" }, "Ángulo °"), h("th", { scope: "col" }, "Vel rad/s"), h("th", { scope: "col" }, "Torque N·m")),
            ),
            this.tbody,
          ),
        ),
        h(
          "section",
          { class: "pv-sheet__battery", "aria-labelledby": "pv-sheet-bat" },
          h("h3", { id: "pv-sheet-bat" }, "Batería"),
          h(
            "dl",
            {},
            h("div", {}, h("dt", {}, "Carga"), this.bat.soc),
            h("div", {}, h("dt", {}, "Corriente"), this.bat.current),
            h("div", {}, h("dt", {}, "Temperatura"), this.bat.temp),
            h("div", {}, h("dt", {}, "Pack"), this.bat.pack),
            h("div", {}, h("dt", {}, "Potencia"), this.bat.power),
          ),
          this.cells,
        ),
      ),
    );
    // Un clic que cae directo en el <dialog> (y no en su contenido) es un clic en el fondo.
    this.dialog.addEventListener("click", (e) => {
      if (e.target === this.dialog) this.toggle(false);
    });
    this.dialog.addEventListener("close", () => onToggle(false));
    this.onToggle = onToggle;
  }

  get open() {
    return this.dialog.open;
  }

  toggle(force = !this.open) {
    if (force === this.open) return;
    if (force) {
      this.dialog.showModal();
      if (this.last) this.update(this.last);
      this.onToggle(true);
    } else {
      this.dialog.close();
    }
  }

  /** Filas agrupadas por pata o miembro; el encabezado del grupo dice si esa pata apoya. */
  build(info) {
    this.rows.clear();
    this.groupLegs = [];
    const names = info?.motores_nombres ?? [];
    const legs = new Set(info?.patas ?? []);
    const rows = [];
    let group = null;
    for (const name of names) {
      const g = motorGroup(name);
      if (g.key !== group) {
        group = g.key;
        const leg = GROUP_LEG[g.key];
        const contact = legs.has(leg) ? h("span", { class: "pv-sheet__contact", "data-contact": "0" }, "—") : null;
        if (contact) this.groupLegs.push({ leg, el: contact });
        rows.push(h("tr", { class: "pv-sheet__group" }, h("th", { scope: "rowgroup", colspan: "5" }, g.label, contact)));
      }
      const pick = h("button", { type: "button", class: "pv-sheet__pick", "aria-pressed": "false", onclick: () => this.onSelect(name) }, h("i", { class: "pv-lamp" }), name);
      const cells = [h("td"), h("td"), h("td"), h("td")];
      const tr = h("tr", { "data-level": "unknown" }, h("th", { scope: "row" }, pick), ...cells);
      rows.push(tr);
      this.rows.set(name, { tr, pick, cells, level: "unknown" });
    }
    this.tbody.replaceChildren(...rows);
  }

  setSelected(name) {
    for (const [n, r] of this.rows) r.pick.setAttribute("aria-pressed", String(n === name));
  }

  update(frame) {
    this.last = frame;
    if (!this.open) return;
    for (const m of frame.motores) {
      const r = this.rows.get(m.nombre);
      if (!r) continue;
      const level = tempLevel(m.temperatura);
      if (level !== r.level) {
        r.tr.setAttribute("data-level", level);
        r.level = level;
      }
      setText(r.cells[0], fmt(m.temperatura, 1));
      setText(r.cells[1], fmt(m.angulo, 1));
      setText(r.cells[2], fmt(m.velocidad, 2));
      setText(r.cells[3], fmt(m.torque, 1));
    }
    for (const { leg, el } of this.groupLegs) {
      const down = frame.fuerzas[leg] === 1;
      el.setAttribute("data-contact", down ? "1" : "0");
      setText(el, down ? "apoyada" : "en el aire");
    }
    this.#updateBattery(frame.bms, frame.derived);
  }

  #updateBattery(bms, d) {
    setText(this.bat.soc, `${fmt(bms.soc, 0)} %`);
    this.bat.soc.setAttribute("data-level", socLevel(bms.soc));
    setText(this.bat.current, `${milliamps(bms.corriente)} · ${currentSense(bms.corriente)}`);
    setText(this.bat.temp, `${fmt(bms.temperatura, 1)} °C`);
    setText(this.bat.pack, bms.celdas.length ? `${fmt(d.packVoltage, 2)} V` : "—");
    setText(this.bat.power, bms.celdas.length ? `${fmt(d.powerW, 1)} W` : "—");

    if (bms.celdas.length !== this.cellChips.length) {
      this.cellChips = bms.celdas.map((_, i) => h("li", {}, h("span", {}, `C${i + 1}`), h("b", {}, "")));
      this.cells.replaceChildren(...this.cellChips);
    }
    bms.celdas.forEach((v, i) => {
      const li = this.cellChips[i];
      setText(li.lastChild, `${fmt(v, 3)} V`);
      li.toggleAttribute("data-low", bms.celdas.length > 1 && v === d.cellMin);
    });
  }
}

