      kind: "hot",
      strong: "FL_calf a 70.0 °C · RR_calf a 65.0 °C",
      rest: " — supera 60 °C. Conviene frenar el robot para que enfríe · y 4 alarmas más.",
      go: true,
    });
    expect(view.stripTarget).toBe("FL_calf");
  });

  test("con un caliente y otra alarma usa el singular", () => {
